  select id, 'L01', 'lesson', 'l01-the-psychology-of-speaking-in-a-second-language', 'The Psychology of Speaking in a Second Language', 'Why fluent clinicians feel less competent in English, and how audiences actually judge non-native speakers.', 60, 1, 1, true, 'not_recorded', 'ready', 'speaking-mentor' from public.modules where number = 1
