insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Many doctors read, write and think in English every working day, yet feel noticeably less competent when they must speak it in front of an audience. A cardiologist who can discuss a complex case fluently with a colleague may lose a familiar word at the lectern, speed up, and retreat to reading the slides. This lesson explains why that happens, what international audiences actually need from you, and how to separate the accuracy of your English from the authority of your expertise. You will finish by identifying your own speaking triggers and replacing the most common self-undermining habit of second-language presenters — the apology — with a clear statement of purpose.","objectives":["Explain how speaking in a second language increases mental workload, and why this affects fluency under pressure","Distinguish accent, comprehensibility and intelligibility, and decide which of them matters most for your audiences","Identify at least three personal speaking triggers and describe their effect on your delivery","Replace an apologetic opening with a clear statement of context, purpose and route"],"sections":[{"heading":"Why fluent clinicians lose words on stage","paragraphs":["Speaking involves several processes running at once: deciding what you want to say, finding the words and grammar to say it, articulating it, and monitoring what you have just said. In your first language, finding the words and building sentences is largely automatic, so your attention is free for the audience and the argument.","In a second language, more of this work needs conscious attention. You search for the precise term, check the grammar of a sentence while you are already halfway through it, and listen to your own pronunciation. Under the pressure of a congress session or a grand round, the attention available to you shrinks further. The result is familiar to most second-language presenters: a word you know perfectly well disappears, sentences become longer and more tangled, and you start speaking faster to reach the end of a sentence before you lose it.","None of this is a sign of weak knowledge. It is a predictable consequence of divided attention. That is good news, because divided attention can be managed. Everything you prepare in advance — your structure, your opening, your transitions, the key terms and how you will pronounce them — no longer has to be produced live, and the attention it frees goes back to your audience."],"callout":{"kind":"evidence","text":"Models of speech production describe planning, formulation and articulation as separate stages that run in parallel. Research on second-language speech describes formulation in a second language as less automatic than in the first language, so it competes for limited attention.","refs":[1,2]}},{"heading":"Accent, comprehensibility and intelligibility","paragraphs":["Three terms are often confused. Accent describes how different your pronunciation sounds from a particular variety of English. Comprehensibility describes how much effort a listener needs to understand you. Intelligibility describes how much of your message the listener actually understands. These are related, but they are not the same: a speaker with a strong accent can be fully intelligible, and a speaker with a mild accent can be hard to follow if the talk is rushed and poorly structured.","For your professional purposes, intelligibility and comprehensibility matter far more than accent. Your audience at an international meeting includes many listeners for whom English is also a second language. They are not comparing you with a newsreader; they are trying to follow your argument while processing technical content in a foreign language themselves.","There is, however, an honest caveat. Speech that is harder to process can be judged less favourably, even when the content is identical. The practical conclusion is not that you should try to hide your accent. It is that you should reduce your listeners'' effort in every other way available to you: a clear structure, explicit signposting, a manageable pace, deliberate pauses and key terms that are stressed correctly and repeated. These are skills you can learn, and the rest of this programme is built around them."],"callout":{"kind":"evidence","text":"In a frequently cited study, listeners'' ratings of accent strength did not reliably predict how much of second-language speech they understood: some heavily accented speech was fully intelligible. A separate experiment found that trivia statements were rated as less likely to be true when spoken with a non-native accent, which the authors attributed to greater processing difficulty. Work on English as an international language argues that a limited set of pronunciation features, including placing the main stress correctly, matters most for mutual intelligibility.","refs":[3,4,5]}},{"heading":"Separating language accuracy from professional credibility","paragraphs":["Credibility on stage rests on three things you already have or can prepare: your expertise, the quality of your preparation, and the clarity of your message. Language accuracy supports credibility, but it is not the same thing. A small slip with an article or a preposition rarely changes how an audience judges your competence. Treating every such slip as a threat increases self-monitoring, which in turn makes more slips likely.","A more useful approach is triage. Some elements of your talk must be accurate, because an error would change the meaning: numbers and units, negatives (“did” versus “did not”), drug names and doses, the names of outcomes, and your conclusions. Other elements can be imperfect without consequence: articles, most prepositions, minor tense errors and word order in a spontaneous answer. Prepare and rehearse the first group carefully; give yourself permission to let the second group go.","Numbers deserve particular attention. “Fifteen” and “fifty”, “thirteen” and “thirty” are easily confused, especially by listeners who are themselves non-native speakers. Show critical numbers on the slide, say them slowly, and where it matters, restate them in another form: “fifteen per cent — that is, roughly one patient in seven”."],"callout":{"kind":"recommendation","text":"Before every talk, list the five pieces of information that must be understood exactly (numbers, doses, outcomes, conclusions) and rehearse those sentences aloud until they are automatic."}},{"heading":"Know your triggers","paragraphs":["Most second-language speakers are not equally anxious in every situation. Common triggers include being interrupted, questions from a senior colleague or a native speaker, a question asked quickly or with an unfamiliar accent, technical failure, being recorded, a strict chair with a timer, and the first minute of a talk. Each trigger tends to produce a recognisable pattern: a faster heartbeat and a dry mouth, but also changes in speech, such as rushing, losing words, over-explaining or falling silent.","Mapping your own triggers is the first practical step towards managing them. For each trigger, note what happens in your body, what happens to your speech, and what you would like to do instead. Then prepare a specific response. If an unclear question is a trigger, you can prepare a clarification phrase and practise it until it is automatic. Preparing the words in advance removes the need to formulate them under pressure, which is exactly when formulation is hardest."]},{"heading":"Opening without apology","paragraphs":["Many second-language speakers open with “Sorry for my English”. The intention is courteous, but the effect is the opposite of what you want: it directs the audience to listen for mistakes, and it frames your first impression around your language rather than your expertise.","Replace the apology with three short moves: context, purpose and route. Context tells the audience why the topic matters to them. Purpose tells them what you want them to take away. Route tells them how the talk is organised. If you are genuinely concerned about being understood, add a functional request rather than an apology: “Please stop me if anything is unclear.” This sounds confident, invites interaction and serves the audience."]}],"examples":[{"title":"Two openings, same content","setting":"International cardiology congress, 10-minute oral presentation","text":"Speaker A begins: “Good morning. Sorry for my English, I will try my best. So, this study is about delirium after cardiac surgery…” and reads a dense first slide quickly. Speaker B, whose accent is stronger, begins: “Good morning. Post-operative delirium affects many of our cardiac surgery patients, and it is often missed. [pause] Today I want to show you one change in our screening that helped us detect it earlier. [pause] I’ll describe what we changed, what we found, and what we are still unsure about.” Most listeners would perceive Speaker B as more confident and more expert, even though Speaker A’s English is more accurate. Speaker B has reduced the listeners’ effort and given them a reason to listen."},{"title":"Losing a word at grand rounds","setting":"Grand round, respiratory medicine, presented by a specialty trainee","text":"Midway through a case, the presenter cannot retrieve the word “pneumothorax”. Instead of stopping, she paraphrases: “The repeat X-ray showed air in the pleural space — the lung had partially collapsed — a pneumothorax.” The word returns as she paraphrases. The audience hears a natural explanation, not a failure. The strategy works because paraphrase uses words that are easier to retrieve under pressure, and it gives the memory a moment to recover the precise term."},{"title":"A fast question from a senior native speaker","setting":"Question-and-answer session after a research presentation","text":"A professor asks a long, rapid question with several clauses. The presenter catches only the end. Rather than guessing, she says: “Thank you. Could I ask you to repeat the first part of your question?” and then: “If I’ve understood you correctly, you’re asking whether the effect persisted beyond six months.” The professor confirms, and her answer is precise. Asking for clarification is standard practice among experienced speakers, including native speakers; it signals care, not weakness."}],"phrase_bank":[{"phrase":"Today I’d like to show you…","use":"Stating your purpose in the opening","register":"Neutral – formal","pronunciation":"Stress “SHOW”; contract “I’d” naturally.","example":"Today I’d like to show you why we changed our screening for delirium."},{"phrase":"What I’d like you to take away is…","use":"Announcing the core message","register":"Neutral","pronunciation":"Stress “TAKE aWAY”.","example":"What I’d like you to take away is that earlier screening changed our practice."},{"phrase":"I’ll start with…, then…, and finally…","use":"Giving the route of the talk","register":"Neutral","example":"I’ll start with the problem, then our intervention, and finally what we are still unsure about."},{"phrase":"Please stop me if anything is unclear.","use":"Replacing an apology for your English","register":"Neutral, courteous","pronunciation":"Fall in pitch on “unCLEAR”.","example":"This is a small group, so please stop me if anything is unclear."},{"phrase":"Let me put that another way.","use":"Repairing a sentence that went wrong, or paraphrasing a word you cannot retrieve","register":"Neutral","example":"Let me put that another way: the lung had partially collapsed."},{"phrase":"In other words, …","use":"Restating a complex point simply","register":"Neutral","example":"Mortality fell by a third. In other words, one death in three was avoided."},{"phrase":"Could I ask you to repeat the last part of your question?","use":"Clarifying a question you did not fully understand","register":"Formal, polite","pronunciation":"Stress “LAST part”.","example":"Thank you. Could I ask you to repeat the last part of your question?"},{"phrase":"If I’ve understood you correctly, you’re asking…","use":"Checking your understanding before answering","register":"Formal","example":"If I’ve understood you correctly, you’re asking whether the effect persisted."},{"phrase":"That’s an important point.","use":"Acknowledging a question while you gather your thoughts","register":"Neutral","pronunciation":"Do not over-use it; once or twice per session.","example":"That’s an important point, and it’s one of the limitations of our data."},{"phrase":"Bear with me for a moment.","use":"Asking for patience during a technical problem or while finding a slide","register":"Neutral, British usage","pronunciation":"“Bear” sounds like “bare”.","example":"Bear with me for a moment — the video should start now."}],"phrase_practice":"Choose three expressions for your next talk: one for the opening, one for repair and one for questions. Write them on your speaker notes, not on the slides, and rehearse each one aloud in a full sentence about your own topic until it comes out without effort.","demonstration":"The instructor video shows the two openings from the congress example delivered back to back, then a short Q&A in which a fast question is clarified with the phrases from this lesson. Watch for where the speaker pauses, how the first sentence states a purpose, and how a key term is said slowly the first time it appears.","mistakes":[{"mistake":"Apologising for your English at the start","correction":"State context, purpose and route; if needed, add “Please stop me if anything is unclear.”"},{"mistake":"Writing a word-for-word script and reading it under pressure","correction":"Script only the opening, transitions and critical sentences; speak the rest from key phrases."},{"mistake":"Correcting small grammar slips aloud","correction":"Continue; correct only errors that change meaning, such as numbers or negatives."},{"mistake":"Guessing the meaning of a question you did not fully hear","correction":"Ask for repetition and paraphrase the question before answering."},{"mistake":"Saying critical numbers quickly","correction":"Show them on the slide, say them slowly, and restate them in another form."}],"reflection":["In which professional speaking situations do you notice the strongest self-monitoring?","Which of your current worries concern language accuracy, and which concern being understood?","Which single habit from this lesson would make the biggest difference to your next talk?"],"references":["Levelt, W. J. M. (1989). Speaking: From Intention to Articulation. Cambridge, MA: MIT Press.","Kormos, J. (2006). Speech Production and Second Language Acquisition. Mahwah, NJ: Lawrence Erlbaum.","Munro, M. J., & Derwing, T. M. (1995). Foreign accent, comprehensibility, and intelligibility in the speech of second language learners. Language Learning, 45(1), 73–97.","Lev-Ari, S., & Keysar, B. (2010). Why don’t we believe non-native speakers? The influence of accent on credibility. Journal of Experimental Social Psychology, 46(6), 1093–1096.","Jenkins, J. (2000). The Phonology of English as an International Language. Oxford: Oxford University Press."]}'::jsonb, '{"title":"Map your speaking triggers","instructions":"Analyse two recent occasions on which you spoke in English to a professional audience, and prepare a response for each trigger you identify.","steps":["Choose two situations from the last year (for example a congress talk, a case presentation, an MDT meeting or a teaching session).","For each, identify the moment you felt least comfortable and what triggered it.","Describe what you noticed in your body and what changed in your speech (pace, lost words, reading, silence).","For each trigger, choose one phrase from the phrase bank, or write your own, that you will use next time."],"prompt":"Write your two situations, triggers, effects and prepared phrases (at least 300 characters).","min_chars":300,"model_answer":"Situation 1: a 7-minute oral presentation at a European nephrology meeting. Trigger: the chair held up a “two minutes” sign before my results section. Body: heart rate rose, hands felt cold. Speech: I started speaking much faster and skipped my conclusion slide. Prepared response: rehearse a 30-second version of my results and conclusion, and say “In the time remaining, let me focus on the main finding.”\n\nSituation 2: a teaching session for international medical students on Zoom. Trigger: a student asked a fast question with an accent I found difficult. Body: felt hot, slight panic. Speech: I guessed what she meant and answered the wrong question. Prepared response: “Could I ask you to repeat the last part of your question?” followed by “If I’ve understood you correctly, you’re asking…”.","self_check":["Each situation is specific (place, audience, type of talk), not general.","The trigger is a concrete event, not a general feeling.","You describe at least one change in your speech, not only in your body.","Each trigger has a prepared phrase you could say word for word."]}'::jsonb, '{"title":"Your speaking profile","brief":"Write a speaking profile of 200–400 words. Describe (1) the professional situations in which you speak English now, (2) your three most important triggers and how they affect your delivery, (3) what you want to be able to do in ten weeks, and (4) one specific talk you would like to give with confidence. You will revisit this profile in Module 12. Do not include any patient-identifiable information.","min_words":200,"required":true,"criteria":[{"criterion":"Specificity","description":"Situations, audiences and talks are concrete and recognisable, not general."},{"criterion":"Self-analysis","description":"Triggers are linked to observable effects on speech (pace, lost words, reading, silence)."},{"criterion":"Goals","description":"The ten-week aims are realistic and connected to the triggers identified."},{"criterion":"Professional language","description":"The text is clear and organised; minor language errors are acceptable."}]}'::jsonb, null, null, null from public.lessons where code = 'L01'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L01');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Why do many fluent professionals find presenting in a second language more tiring than speaking in their first language?', array['Their medical knowledge is weaker in the second language', 'Formulating speech in a second language is less automatic and competes for attention', 'International audiences are more critical than local audiences', 'Slides are harder to design in English']::text[], 1, 'Second-language formulation needs more conscious attention, so it competes with memory, fluency and attention to the audience. It is not a sign of weaker knowledge.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Which statement about accent and intelligibility is most accurate?', array['A stronger accent always means lower intelligibility', 'Accent has no effect on how listeners judge a speaker', 'Heavily accented speech can be fully intelligible, but harder-to-process speech may be judged less favourably', 'Intelligibility depends only on grammar']::text[], 2, 'Accent and intelligibility are related but distinct. Research shows accented speech can be fully intelligible; it also suggests processing difficulty can affect judgements, which is why reducing listener effort matters.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You are about to present at an international congress and feel worried about your English. Which opening is best?', array['“Sorry for my English, I will try my best.”', '“My English is not perfect, so please be patient with me.”', '“Today I’d like to show you one change that improved our outcomes. Please stop me if anything is unclear.”', 'Start directly with the methods slide to save time']::text[], 2, 'A statement of purpose builds credibility, and a functional request serves the audience without drawing attention to your language.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'During your talk you say “the patients was” instead of “the patients were”. What should you do?', array['Stop and correct the sentence explicitly', 'Continue with your message', 'Apologise to the audience', 'Repeat the whole slide']::text[], 1, 'This error does not change the meaning. Correcting it aloud draws attention to it and interrupts your flow. Correct only errors that change meaning.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'A senior professor asks a long, fast question and you understand only the final part. What is the most professional response?', array['Answer the part you understood and hope it was the main point', 'Ask the chair to answer instead', 'Ask for the first part to be repeated, then paraphrase the question before answering', 'Say that you will answer after the session']::text[], 2, 'Clarifying and paraphrasing is standard practice among experienced speakers. It ensures you answer the right question and signals care.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'Which of these must be rehearsed until it is completely accurate?', array['Every article and preposition in the talk', 'Numbers, doses, negatives and your conclusions', 'Your accent', 'The exact wording of every answer to possible questions']::text[], 1, 'Errors in numbers, doses, negatives or conclusions change the meaning. Minor grammatical slips usually do not.' from public.lessons where code = 'L01';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L01');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L01 Lesson handout', 'Key points, phrase bank and the speaking-trigger worksheet.', '/materials/lessons/L01-handout.pdf', false from public.lessons where code = 'L01';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L02', 'lesson', 'l02-from-nervous-energy-to-focused-presence', 'From Nervous Energy to Focused Presence', 'Practical pre-performance routines: breathing, grounding, and the first thirty seconds.', 60, 1, 2, false, 'not_recorded', 'ready', 'speaking-mentor' from public.modules where number = 1
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Every experienced speaker feels some arousal before an important talk: a faster heartbeat, a dry mouth, restless hands. For many second-language speakers these sensations are stronger, and they arrive exactly when the extra effort of speaking in English is greatest. This lesson treats nervousness as something to manage rather than eliminate. You will learn what is happening in your body, how the way you interpret it changes your performance, and how to build a short, reliable routine for the day, the hour and the minute before you speak. You will also prepare the most difficult part of any talk — the first thirty seconds — and a recovery plan for the moment your mind goes blank.","objectives":["Recognise the physical and verbal signs of performance arousal in yourself","Apply a reappraisal statement and a slow-breathing routine before speaking","Write and rehearse an opening of no more than 70 words with planned pauses","Use a three-step recovery technique when you lose your place during a talk"],"sections":[{"heading":"What your body is doing, and why it is not the enemy","paragraphs":["Before a talk, your body prepares for a demanding task. Stress hormones raise your heart rate and breathing, redirect blood flow and sharpen attention to threat. The signs are familiar: palpitations, a dry mouth, cold hands, a tight throat and an urge to move. In speech, the same arousal often shows as a faster pace, a higher pitch, shallow breathing that leaves you short of air at the end of sentences, and a tendency to rush through the opening.","A common goal is to stop feeling nervous. It is also an unrealistic one. Arousal is partly automatic, and trying to suppress it usually increases self-monitoring — the very process that already competes for attention when you speak a second language. A more useful goal is regulation: bringing arousal into a range in which it sharpens rather than scatters your attention, and keeping its effects on your speech under control.","It helps to separate the sensation from the story you tell about it. The sensation is physical. The story — “I am going to fail” or “my body is getting ready to perform” — is an interpretation, and it is the interpretation you can change."]},{"heading":"Reappraisal: changing the interpretation, not the feeling","paragraphs":["Reappraisal means deliberately reinterpreting arousal as a resource. Instead of telling yourself to calm down, you name the sensation as preparation: “This is energy. My body is getting ready.” The advantage is that this statement is true, so you do not have to argue with your own heartbeat.","Use a short sentence that you can say silently in the minutes before you speak. Some speakers prefer “I am excited to share this”; others prefer a more neutral version such as “This energy will help me focus.” Choose wording you can say honestly. Rehearse it in low-stakes situations first, such as before a ward meeting or a journal club, so that it is automatic when the stakes are high."],"callout":{"kind":"evidence","text":"In laboratory studies, participants instructed to reinterpret pre-performance arousal as helpful showed more adaptive physiological responses, and participants who said “I am excited” before a public speaking task were rated as more persuasive, competent and confident than those who tried to calm down.","refs":[1,2]}},{"heading":"Slow breathing","paragraphs":["Breathing is the one part of the stress response you can control directly. Slow breathing with an exhale that is longer than the inhale is widely used to reduce physiological arousal. A practical pattern is to inhale through the nose for four counts and exhale gently through the mouth for six counts, for about two minutes. Nobody in the room needs to notice; you can do it while waiting to be introduced.","Breathing also matters during the talk. Anxious speakers often take shallow breaths and then try to say a long sentence on what remains. Plan short sentences and natural breathing points in your opening, and breathe at every pause. A breath taken at a pause is invisible to the audience; a sentence that runs out of air is not."],"callout":{"kind":"evidence","text":"A systematic review of slow-breathing techniques (around six breaths per minute) reported associations with increased heart-rate variability, relaxation and reduced anxiety. The four-in, six-out pattern used here is a practical recommendation based on this approach rather than a tested protocol for presentations.","refs":[3]}},{"heading":"A pre-speaking routine: the day, the hour, the minute","paragraphs":["Routines work because they replace decisions with habits. On the day before, finish your slides, rehearse the full talk aloud once with a timer, and rehearse the opening and conclusion several times. Do not plan to make major changes on the day itself.","One hour before, check the room and the technology: the clicker, the laser pointer, the microphone, the video files and the timer the chair will use. Then stop editing. Last-minute changes create new material that has not been rehearsed, which increases load at the worst possible moment.","Ten minutes before, do two minutes of slow breathing and say your reappraisal statement. Drink water to prevent a dry mouth. One minute before, stand or sit with both feet on the floor, feel the contact, and silently rehearse your first sentence. When you reach the lectern, arrange your notes, look at the audience, and take one breath before you speak. The silence will feel long to you and normal to everyone else."],"callout":{"kind":"recommendation","text":"Rehearse the routine itself, not only the talk. Use it before smaller occasions for two or three weeks so that it becomes automatic."}},{"heading":"The first thirty seconds","paragraphs":["Arousal usually peaks in the opening, and this is where second-language speakers most often rush. Prepare the first thirty seconds word for word: no more than 70 words, in short spoken sentences, with at least two marked pauses. Use the structure from Lesson 1: context, purpose and route. Rehearse it aloud until it feels natural, and then rehearse it standing up, because posture changes breathing and voice.","Open with a sentence that is easy to say. Avoid starting with long technical terms, numbers or complex grammar. “Good morning. Thank you, Chair” is followed by a pause, then by a short sentence that tells the audience why the topic matters. Once the opening is behind you, most speakers find their rhythm. You are not memorising the whole talk; you are building a reliable way into it."]},{"heading":"When your mind goes blank","paragraphs":["Almost every speaker loses their place at some point. What distinguishes experienced speakers is not that it never happens, but that they have a plan. Use three steps. First, pause and breathe; a silence of three or four seconds is not noticed as a problem. Second, look at your slide or your notes for the key phrase. Third, bridge back with a short summary of what you have just said: “So, to recap — the screening was feasible. Let me now turn to the results.”","Summarising buys time, helps the audience, and usually brings back the next point. Prepare one recap sentence for each section of your talk in advance, so that you never have to compose it under pressure."]},{"heading":"A note on medication","paragraphs":["Some clinicians ask about medication for performance anxiety. This is a clinical decision for the individual and their own doctor, and it is outside the scope of this programme. The techniques in this lesson are educational and can be used alongside any approach you choose."]}],"examples":[{"title":"A rehearsed opening","setting":"Orthopaedic surgery meeting, 8-minute quality-improvement presentation","text":"“Good morning. Thank you, Chair. [pause] After hip surgery, many of our patients had a urinary catheter for two or three days. [pause] Today I want to show you what happened when we stopped doing that routinely — and what happened to our infection rates. [pause] I’ll cover what we changed, what we measured, and the questions it raised.” The opening is 60 words, uses short sentences, states the purpose and gives the route. The speaker rehearsed it twelve times over three days and said it was the only part of the talk she did not worry about."},{"title":"A physical cue to start","setting":"Cardiology grand round, presenter waiting to be introduced","text":"While the chair introduces him, a consultant cardiologist breathes slowly, four counts in and six out, and silently repeats “This energy will help me focus.” At the lectern, he places his notes down, rests both palms flat on the lectern for two seconds, looks at the back row, and begins. The gesture is invisible to the audience but signals to him that preparation is over and the talk has started."},{"title":"Recovering from a blank","setting":"Journal club presented by a research fellow, online","text":"Halfway through, the fellow loses the thread after a question in the chat. She pauses, takes a breath and looks at her slide title, “Limitations”. She says: “So, to recap — the trial was well designed, and the effect was clinically meaningful. Let me now turn to its limitations.” The audience experiences a natural transition. The recap took eight seconds and gave her time to retrieve her next point."}],"phrase_bank":[{"phrase":"Thank you, Chair.","use":"Acknowledging the chair before you begin","register":"Formal, standard at congresses","pronunciation":"Pause after it; do not run it into your first sentence.","example":"Thank you, Chair. [pause] Good morning, everyone."},{"phrase":"Good morning, everyone.","use":"Greeting the audience","register":"Neutral","example":"Good morning, everyone. Thank you for staying for the last session."},{"phrase":"Let me start with a question.","use":"Opening with engagement rather than data","register":"Neutral","example":"Let me start with a question: how many of your patients go home with a catheter?"},{"phrase":"Over the next ten minutes, I’ll…","use":"Giving a timed route","register":"Neutral","pronunciation":"Stress “TEN MINutes”.","example":"Over the next ten minutes, I’ll show you what we changed and what we found."},{"phrase":"So, to recap…","use":"Summarising to recover your place or close a section","register":"Neutral","example":"So, to recap — the intervention was feasible and safe."},{"phrase":"Let me pick up where I left off.","use":"Returning after an interruption","register":"Neutral","example":"Thank you for that question. Let me pick up where I left off."},{"phrase":"Let me now turn to…","use":"Moving to the next section","register":"Neutral – formal","example":"Let me now turn to the results."},{"phrase":"Bear with me while I fix this.","use":"Handling a technical problem calmly","register":"Neutral, British usage","example":"Bear with me while I fix this — in the meantime, let me describe the patients."},{"phrase":"While that loads, …","use":"Filling time productively during a delay","register":"Informal – neutral","example":"While that loads, let me tell you why we chose this outcome."},{"phrase":"I’ll come back to that in a moment.","use":"Postponing a point or question you are not ready for","register":"Neutral","example":"That’s a good question — I’ll come back to that in a moment, when I show the subgroup data."}],"phrase_practice":"Write your opening using two or three of these expressions, then write one recap sentence for each section of your talk. Say all of them aloud, standing, at your normal presentation volume.","demonstration":"The instructor video demonstrates the four-in, six-out breathing pattern, then delivers the orthopaedic opening twice: first rushed and without pauses, then as rehearsed. It ends with a staged “blank” and the three-step recovery.","mistakes":[{"mistake":"Editing slides in the final hour","correction":"Finish the day before; use the final hour for technical checks and your routine."},{"mistake":"Trying to suppress all signs of nervousness","correction":"Reappraise the sensation as energy and regulate it with slow breathing."},{"mistake":"Improvising the first sentence","correction":"Script and rehearse the first 30 seconds word for word."},{"mistake":"Starting to speak while walking to the lectern","correction":"Arrive, arrange your notes, look at the audience, breathe, then begin."},{"mistake":"Apologising when you lose your place","correction":"Pause, look at your notes, and bridge back with a recap sentence."}],"reflection":["Which part of the routine feels most natural to you, and which feels awkward?","Where in the coming week can you practise the routine in a low-stakes setting?","What reappraisal statement can you say honestly?"],"references":["Jamieson, J. P., Nock, M. K., & Mendes, W. B. (2012). Mind over matter: Reappraising arousal improves cardiovascular and cognitive responses to stress. Journal of Experimental Psychology: General, 141(3), 417–422.","Brooks, A. W. (2014). Get excited: Reappraising pre-performance anxiety as excitement. Journal of Experimental Psychology: General, 143(3), 1144–1158.","Zaccaro, A., Piarulli, A., Laurino, M., Garbella, E., Menicucci, D., Neri, B., & Gemignani, A. (2018). How breath-control can change your life: A systematic review on psycho-physiological correlates of slow breathing. Frontiers in Human Neuroscience, 12, 353."]}'::jsonb, '{"title":"Write and rehearse your first thirty seconds","instructions":"Prepare the opening of a presentation you are likely to give in the coming months.","steps":["Write an opening of no more than 70 words using context, purpose and route.","Mark at least two pauses with [pause]. Keep sentences short.","Underline any word that is hard for you to pronounce; if possible, replace it in the opening.","Rehearse it aloud five times, at least twice standing up.","Write one recap sentence you could use if you lost your place after the introduction."],"prompt":"Paste your opening (with pauses marked) and your recap sentence.","min_chars":250,"model_answer":"Opening (64 words): “Good morning. Thank you, Chair. [pause] In our emergency department, one in five older patients waits more than four hours for analgesia. [pause] Today I want to show you how a nurse-initiated protocol changed that — and where it did not. [pause] I’ll describe the protocol, our results over twelve months, and what we would do differently.”\n\nRecap sentence: “So, to recap — delays were common, and they were longest at night. Let me now turn to what we changed.”","self_check":["The opening is 70 words or fewer.","It states why the topic matters, what you will show, and how the talk is organised.","There are at least two pauses, and no sentence is longer than about 20 words.","The first sentence after the greeting contains no difficult terms or long numbers.","The recap sentence summarises and announces the next section."]}'::jsonb, '{"title":"Your pre-speaking routine","brief":"Write your personal pre-speaking routine (200–350 words) for the day before, one hour before, ten minutes before and one minute before speaking, including your reappraisal statement. Then use it before one low-stakes speaking situation this week and describe briefly what happened and what you would change.","min_words":200,"required":true,"criteria":[{"criterion":"Completeness","description":"All four time points are covered with specific, realistic actions."},{"criterion":"Personalisation","description":"The routine reflects your own triggers from Lesson 1, not a generic list."},{"criterion":"Application","description":"It was tried in a real situation, with an honest description of the result."},{"criterion":"Reflection","description":"At least one concrete adjustment is proposed."}]}'::jsonb, null, null, null from public.lessons where code = 'L02'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L02');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'What is a realistic goal for nervousness before an important talk?', array['Eliminate it completely', 'Regulate it so that it supports focus', 'Ignore it', 'Increase it with caffeine']::text[], 1, 'Arousal is partly automatic. Trying to suppress it increases self-monitoring; regulating it is achievable and useful.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Which statement best describes reappraisal?', array['Telling yourself to calm down', 'Reinterpreting the sensation of arousal as energy or preparation', 'Avoiding situations that cause anxiety', 'Memorising the whole talk']::text[], 1, 'Reappraisal changes the interpretation of the sensation, not the sensation itself. Research suggests it can improve stress responses and performance.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'Which breathing pattern is recommended in this lesson?', array['Exhale for longer than you inhale', 'Inhale for longer than you exhale', 'Hold your breath for ten seconds', 'Breathe as quickly as possible']::text[], 0, 'Slow breathing with a longer exhale, such as four counts in and six out, is widely used to reduce arousal.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'It is 40 minutes before your talk and you notice a typing error on slide 9. What should you do?', array['Rewrite slides 8 to 10 to improve them', 'Fix the typing error only if it is quick and safe, then stop editing', 'Ignore the technical check to make time for improvements', 'Add a new slide explaining the error']::text[], 1, 'Small, safe corrections are fine. Major edits in the final hour create unrehearsed material and increase load.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'After a question from the audience, you cannot remember what comes next in your talk. What is the best first step?', array['Apologise and say you have lost your place', 'Skip to your conclusion', 'Pause, breathe, look at your notes, and bridge back with a recap sentence', 'Read the next slide word for word']::text[], 2, 'A short pause is not noticed as a problem. A recap sentence helps the audience and brings back your next point.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'Which of these is the strongest opening sentence after “Thank you, Chair”?', array['“The primary endpoint was the incidence of catheter-associated urinary tract infection at thirty days in patients over sixty-five.”', '“After hip surgery, many of our patients had a urinary catheter for two or three days.”', '“Sorry, I am a little nervous today.”', '“I will now present my research.”']::text[], 1, 'It is short, easy to say, and tells the audience why the topic matters. Long technical sentences are hardest to deliver at peak arousal.' from public.lessons where code = 'L02';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L02');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L02 Lesson handout', 'Routine checklist, opening template and recovery steps.', '/materials/lessons/L02-handout.pdf', false from public.lessons where code = 'L02';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L03', 'lesson', 'l03-building-a-speaker-identity', 'Building a Speaker Identity', 'Defining the professional voice you want to be known for, and setting your ten-week development goals.', 55, 1, 3, false, 'not_recorded', 'ready', 'speaking-mentor' from public.modules where number = 1
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Authority in medical speaking does not come from sounding like someone else. It comes from a clear sense of what you know, how you want to be heard, and what you are working to improve. This lesson turns the general wish to “be more confident” into a professional speaker identity and a concrete development plan. You will audit the strengths you already bring as a clinician or researcher, define the voice you want audiences to recognise, learn the language of measured scientific confidence, and set three specific, observable goals for the ten weeks of the programme — starting from an honest baseline recording of how you speak today.","objectives":["Identify at least three strengths you already bring to professional speaking","Define your professional voice in three words and link each word to a concrete delivery choice","Use appropriate hedging and boosting language to sound confident without overstating evidence","Write three specific, observable goals with if–then plans and a baseline for each"],"sections":[{"heading":"What authority means for a medical speaker","paragraphs":["Audiences at medical meetings judge speakers quickly, and they judge them on more than language. A useful framework, which goes back to classical rhetoric, distinguishes three sources of persuasion: the credibility of the speaker, the logic of the argument, and the connection with the audience. For a medical speaker, credibility comes from expertise and integrity: knowing the field, being precise about what the evidence shows, and being honest about its limits. Logic comes from a clear structure and a well-chosen core message. Connection comes from showing why the topic matters to the people in the room.","Notice that none of these depends on a native accent. A second-language speaker who is precise, well organised and relevant has every source of authority available. The work of this programme is to make those qualities audible: to deliver them clearly enough that the audience recognises them."]},{"heading":"Strengths you already have","paragraphs":["Medical professionals bring real advantages to the podium, and it is worth naming them explicitly. You explain complex information to patients and families, often under time pressure and in difficult circumstances. You present cases in a structured way, from history to plan. You are used to reasoning from evidence, weighing uncertainty and making decisions. Many of you teach students and junior colleagues. Some of you have experience of speaking in two or three languages, which gives you a sharp awareness of how meaning can be lost.","Begin with an audit. List the situations in which you already communicate well — a family meeting, a handover, a bedside teaching session — and ask what you do there that works. Often the answer is surprisingly transferable: you slow down for a worried family, you check understanding, you choose simple words for a complex idea. These are presentation skills. Part of your development is simply bringing them onto the stage."]},{"heading":"Defining your professional voice","paragraphs":["Choose three words that you would like an audience to use about you after a talk: for example “clear, practical, warm” or “precise, calm, curious”. Avoid words that describe a personality you do not have. A calm and precise speaker does not need to become theatrical to be effective; trying to perform a different personality adds yet another task to an already demanding situation.","Each word should guide concrete choices. “Clear” might mean one message per slide and a summary at the end of each section. “Practical” might mean ending every talk with what the audience can do on Monday. “Curious” might mean opening with a genuine question from your own practice. Writing down these links turns an abstract identity into decisions you can rehearse and evaluate."],"callout":{"kind":"recommendation","text":"Write your three words on the first page of your speaker notes for every talk during the programme, and check one delivery choice against each word when you rehearse."}},{"heading":"The language of measured confidence","paragraphs":["Scientific English has a particular way of sounding confident. Overstating results (“this proves”) damages credibility with expert audiences, but excessive caution (“maybe it could perhaps be possible that”) sounds uncertain. Authority lies in matching the strength of your language to the strength of your evidence.","Use boosters when the evidence is strong: “clearly”, “consistently”, “the data show”. Use hedges when it is not: “our data suggest”, “this may reflect”, “in our population”. Distinguish your findings from your interpretation: “We found…; we think this is because…”. State limitations directly rather than apologetically: “The main limitation is the sample size.” Second-language speakers often either avoid hedging altogether or stack several hedges in one sentence. One accurate hedge, placed where the uncertainty actually lies, is both more confident and more honest."]},{"heading":"Goals that can be observed and measured","paragraphs":["Vague goals such as “be more confident” or “improve my English” are hard to act on and impossible to evaluate. Useful speaking goals describe behaviour that you or an observer can see or measure: speaking at a comfortable pace, pausing before each key result, opening without an apology, or answering three questions without looking at your notes.","Add an if–then plan to each goal: a specific situation and a specific action. “If the chair shows the two-minute sign, then I will move to my conclusion slide and say my take-home message.” Plans of this kind link the goal to the moment when you need it, which is precisely when you have least attention to spare."],"callout":{"kind":"evidence","text":"Research on goal setting has found that specific, challenging goals generally lead to better performance than vague instructions to “do your best”. Studies of implementation intentions — plans in the form “if situation X, then I will do Y” — have found that they help people act on their goals.","refs":[1,2]}},{"heading":"Establish a baseline, then practise deliberately","paragraphs":["You cannot see progress without a starting point. Record yourself giving a two-minute summary of your current work, as you would at the start of a conference talk. Use your phone or a laptop; in a later stage of the programme, the Speaking Studio will measure aspects such as pace and filler words for you. Listen once for content and once for delivery, and note what you hear: pace, pauses, fillers, and moments where you search for words.","Improvement comes from focused practice on one element at a time, with feedback, rather than from simply repeating whole talks. Choose one goal per week, practise it in short sessions, and record again. Over ten weeks, a sequence of short, targeted recordings is far more valuable than a single rehearsal the night before a congress."],"callout":{"kind":"evidence","text":"Research on expert performance distinguishes deliberate practice — focused effort on specific aspects of performance, with feedback — from simple repetition, and associates it with the development of expertise.","refs":[3]}}],"examples":[{"title":"From vague to measurable","setting":"Consultant anaesthetist preparing for a national meeting","text":"Her initial goal was “to sound more confident in English”. After the baseline recording, she noticed that she spoke very quickly in the first minute and said “so” at the start of most sentences. Her revised goals were: “Open every talk with a rehearsed 60-word introduction and two pauses”; “Reduce sentence-initial ‘so’ to no more than three per five minutes”; and “If I am asked a question I did not fully understand, then I will paraphrase it before answering.” Each goal could be checked in her next recording."},{"title":"Three words in practice","setting":"Paediatric neurologist who teaches international fellows","text":"She chose “clear, calm, curious”. Clear: one message per slide, stated in the slide title as a full sentence. Calm: a deliberate pause before every data slide. Curious: each teaching session opens with a real clinical question from her practice, such as “Why did this child’s seizures stop when we changed nothing?”. After three weeks, fellows began to describe her sessions in almost exactly those words, without knowing she had chosen them."},{"title":"Measured confidence in a results statement","setting":"Research fellow presenting a single-centre observational study","text":"First draft: “This study proves that early mobilisation reduces delirium, maybe, in some patients, possibly.” The sentence both overstates and undermines the finding. Revised: “In our cohort, patients who were mobilised within 24 hours had fewer episodes of delirium. Because this was an observational study in one centre, we can’t exclude confounding; a randomised trial is the next step.” The revision is more cautious about causation and, at the same time, sounds more authoritative."}],"phrase_bank":[{"phrase":"My work focuses on…","use":"Introducing your expertise briefly","register":"Neutral – formal","example":"I’m a consultant nephrologist, and my work focuses on dialysis in older adults."},{"phrase":"What I’d like to share is based on…","use":"Establishing the source of your authority","register":"Neutral","example":"What I’d like to share is based on five years of data from our unit."},{"phrase":"Our data suggest that…","use":"Hedging a finding appropriately","register":"Formal, scientific","pronunciation":"Note: “data” is usually plural in scientific British English (“data suggest”).","example":"Our data suggest that early screening detects delirium sooner."},{"phrase":"The evidence for this is strong.","use":"Boosting when the evidence justifies it","register":"Formal","example":"The evidence for this is strong: three large trials point in the same direction."},{"phrase":"We found…; we think this is because…","use":"Separating results from interpretation","register":"Neutral, scientific","example":"We found fewer readmissions; we think this is because follow-up calls happened earlier."},{"phrase":"The main limitation is…","use":"Stating limitations directly","register":"Formal","pronunciation":"Stress “MAIN limiTAtion”.","example":"The main limitation is that this was a single-centre study."},{"phrase":"In our experience…","use":"Signalling professional experience rather than formal evidence","register":"Neutral","example":"In our experience, families find this explanation easier to follow."},{"phrase":"Speaking as a clinician rather than a researcher, …","use":"Clarifying the perspective you speak from","register":"Neutral – formal","example":"Speaking as a clinician rather than a researcher, I find this result reassuring."},{"phrase":"I’d welcome your thoughts on…","use":"Inviting discussion confidently","register":"Formal, collegial","example":"I’d welcome your thoughts on how this might work in smaller hospitals."},{"phrase":"We don’t yet know whether…","use":"Acknowledging uncertainty with authority","register":"Neutral","example":"We don’t yet know whether the effect lasts beyond a year."}],"phrase_practice":"Write a 60-second self-introduction for a congress session using three of these expressions: one to introduce your work, one to hedge a finding, and one to state a limitation. Record it and check that your hedges sit exactly where the uncertainty lies.","demonstration":"The instructor video shows the same speaker giving two self-introductions: one generic and one built around three chosen words. It then presents the research fellow’s results statement in its first and revised versions.","mistakes":[{"mistake":"Copying the style of a speaker whose personality is very different from yours","correction":"Choose three words that describe the best version of your own style."},{"mistake":"Setting goals that cannot be observed","correction":"Describe behaviour you could see in a recording, such as pauses, pace or openings."},{"mistake":"Setting many goals at once","correction":"Choose three goals and focus on one per week."},{"mistake":"Overstating results (“this proves…”)","correction":"Match the strength of your language to the strength of the evidence."},{"mistake":"Stacking hedges (“maybe it could possibly…”)","correction":"Use one accurate hedge where the uncertainty actually lies."}],"reflection":["Which three words would you like an audience to use about you, and which delivery choice supports each one?","Which goal would make the biggest difference to your professional work in the next year?","What did your baseline recording show that surprised you?"],"references":["Locke, E. A., & Latham, G. P. (2002). Building a practically useful theory of goal setting and task motivation: A 35-year odyssey. American Psychologist, 57(9), 705–717.","Gollwitzer, P. M. (1999). Implementation intentions: Strong effects of simple plans. American Psychologist, 54(7), 493–503.","Ericsson, K. A., Krampe, R. T., & Tesch-Römer, C. (1993). The role of deliberate practice in the acquisition of expert performance. Psychological Review, 100(3), 363–406."]}'::jsonb, '{"title":"Three words, three goals","instructions":"Define your professional voice and turn your development into observable goals.","steps":["Record a two-minute summary of your current work and listen to it twice: once for content, once for delivery.","Choose three words for your professional voice and link each to one concrete delivery choice.","Write three observable goals based on what you heard in your recording.","Add an if–then plan to each goal."],"prompt":"Your three words with delivery choices, and three goals with if–then plans (at least 300 characters).","min_chars":300,"model_answer":"Three words: precise (each data slide has one take-home sentence in the title); calm (I pause before every result); practical (I end with what clinicians can change next week).\n\nGoal 1: Open every talk with a rehearsed introduction of under 70 words. If I feel my heart rate rise at the lectern, then I will breathe once and say my first scripted sentence.\nGoal 2: Reduce fillers (“so”, “eh”) to no more than five in a five-minute recording. If I notice a filler, then I will pause silently before the next sentence.\nGoal 3: Paraphrase every question before answering. If a question is longer than one sentence, then I will say “If I’ve understood you correctly, you’re asking…”.","self_check":["Each word is linked to a choice you could observe in a recording.","Each goal is based on something you heard in your baseline recording.","Each goal can be checked as achieved or not achieved.","Each if–then plan names a specific situation and a specific action."]}'::jsonb, '{"title":"Your ten-week development plan","brief":"Write a development plan of 250–400 words. Describe your baseline recording (what you noticed about pace, pauses, fillers and word-finding), your three words with their delivery choices, and your three goals with if–then plans. For each goal, explain why it matters in your professional context and how you will know you have achieved it by Week 10.","min_words":250,"required":true,"criteria":[{"criterion":"Baseline","description":"The plan refers to specific observations from a real recording."},{"criterion":"Observable goals","description":"Each goal could be checked in a later recording or by an observer."},{"criterion":"Implementation","description":"Each goal has a realistic if–then plan tied to a real situation."},{"criterion":"Relevance","description":"Goals are connected to the speaker’s actual professional speaking context."}]}'::jsonb, null, null, null from public.lessons where code = 'L03'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L03');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Which of these is an observable speaking goal?', array['Be more confident', 'Sound more professional', 'Pause before stating each key result', 'Improve my English']::text[], 2, 'An observable goal describes behaviour you could see or hear in a recording.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'What is the main purpose of an if–then plan?', array['To make goals sound more ambitious', 'To link a goal to the specific situation in which you need to act', 'To replace rehearsal', 'To impress the audience']::text[], 1, 'If–then plans connect the goal to the moment of action, when attention is limited. Research suggests they help people act on their goals.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You present a single-centre observational study. Which sentence matches the strength of the evidence?', array['“This study proves that early mobilisation prevents delirium.”', '“Maybe it could possibly be that mobilisation perhaps helps.”', '“In our cohort, early mobilisation was associated with fewer episodes of delirium.”', '“Mobilisation is the cure for delirium.”']::text[], 2, '“Was associated with” is accurate for observational data; it avoids both overstatement and excessive hedging.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'A colleague with a very theatrical style is admired in your department. You are naturally calm and precise. What should you do?', array['Copy the colleague’s gestures and jokes', 'Develop your own calm and precise style and make it clearly audible', 'Avoid presenting until you feel more theatrical', 'Speak louder and faster to sound energetic']::text[], 1, 'Authority comes from expertise, clarity and integrity. Performing a different personality adds load and rarely sounds authentic.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'Which approach to practice is most likely to improve your speaking?', array['Rehearsing the whole talk many times the night before', 'Focused practice on one element at a time, with recordings and feedback', 'Reading your slides aloud silently', 'Waiting until the talk and relying on adrenaline']::text[], 1, 'Research on expert performance associates focused, feedback-based practice with improvement more than simple repetition.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'Your study had a small sample. How should you state this limitation?', array['Do not mention it', '“Sorry, I know the study is very weak.”', '“The main limitation is the sample size, so these findings need confirmation in a larger cohort.”', 'Mention it only if someone asks']::text[], 2, 'Stating limitations directly, without apology, is a mark of scientific credibility.' from public.lessons where code = 'L03';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L03');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L03 Lesson handout', 'Strengths audit, three-words worksheet, goal and if–then planner, hedging phrases.', '/materials/lessons/L03-handout.pdf', false from public.lessons where code = 'L03';

insert into public.modules (number, slug, title, weeks_label, summary, outcomes) values (2, 'english-speaking-foundations', 'English Speaking Foundations', 'Weeks 1–2', 'Prioritise intelligibility over accent. Learn the stress, rhythm and signposting patterns that make spoken English easy for international audiences to follow.', array['Use word and sentence stress to make key medical terms clear', 'Replace written-style sentences with spoken-style English', 'Signpost a talk so listeners never lose the thread']::text[])
