insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L07', 'lesson', 'l07-pace-pause-and-emphasis', 'Pace, Pause and Emphasis', 'Why speakers rush in a second language, and how pauses create authority and comprehension.', 60, 2, 1, false, 'sample', 'ready', 'voice-coach' from public.modules where number = 3
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Under pressure, most presenters speed up. In a second language the effect is stronger: we hurry to reach the end of a sentence before we lose the words, and we fill every silence because silence feels like failure. The audience pays the price. Listeners need time to process technical information, and many of them are processing it in a second language too. This lesson gives you control over three features of delivery that strongly affect how easily you are understood: pace, pausing and emphasis. You will measure your own pace, learn where pauses help and where they hurt, and practise placing stress on the words that carry your meaning — including the numbers that international audiences most often mishear.","objectives":["Measure your speaking rate from a recording and compare it with a practical target range","Divide spoken sentences into thought groups and place deliberate pauses before and after key messages","Place sentence stress on the word that carries the main information, including contrastive stress","Deliver numbers and data so that they are heard correctly by international audiences"],"sections":[{"heading":"Pace: how fast is too fast?","paragraphs":["There is no single correct speaking rate, but there is a practical range. Many presentation coaches recommend around 130 to 160 words per minute for international medical audiences, slower for dense data and faster for a story or a familiar point. Treat this as professional guidance, not a rule. A good pace is one at which your audience can follow your reasoning and still has a moment to think about what you have just shown them.","Measure your own pace rather than guessing. Record one minute of a talk, transcribe it or use an automatic transcript, and count the words. Many speakers are surprised: under pressure, rates above 180 words per minute are common, and they rarely feel fast to the speaker. In a later stage of the programme, the Speaking Studio will calculate this for you and show where in the talk you accelerate.","If you are short of time, cut content rather than speeding up. Speaking faster saves seconds but costs comprehension, and it usually increases errors and fillers. Decide in advance which slide you will skip if the chair shows you the two-minute sign."],"callout":{"kind":"recommendation","text":"The 130–160 words-per-minute range is a widely used professional guideline, not a research-derived threshold. Use your own recordings, and your audience’s reactions, to find your best pace."}},{"heading":"Thought groups and the deliberate pause","paragraphs":["Fluent speakers do not pause randomly. They divide speech into thought groups — short units of meaning, often a phrase or a clause — and pause briefly between them. “In our cohort / of four hundred patients / readmissions fell / by a third.” Each group is easy to say on one breath and easy to process. Pausing in the middle of a unit, such as between an adjective and its noun or in the middle of a technical term, has the opposite effect.","Longer, deliberate pauses do specific work. A pause before a key result creates attention: the audience senses that something important is coming. A pause after it gives them time to absorb it. A pause when you show a new slide lets the audience read before you speak, so they are not choosing between your voice and the screen. These pauses feel very long to the speaker — two or three seconds can feel like ten — but they sound confident and controlled to listeners."]},{"heading":"Fillers: what they are and what to do about them","paragraphs":["Fillers such as “um”, “uh”, “so” and “you know” are often presented as errors. The reality is more nuanced. In ordinary conversation, fillers can signal that the speaker is planning the next words, and listeners use them. They are a normal feature of speech, including the speech of fluent native speakers.","In a formal presentation, however, frequent fillers can distract, and in a second language they often increase when you search for words. The aim is not to eliminate them completely, which tends to increase anxiety, but to reduce them by replacing many of them with silent pauses. A silent pause gives you the same planning time and sounds more authoritative. Start by noticing where your fillers cluster: very often they appear at the start of sentences and at slide transitions, which are exactly the moments you can prepare."],"callout":{"kind":"evidence","text":"Research on spontaneous speech suggests that “uh” and “um” are used to signal upcoming delays, and that listeners make use of them in comprehension. This is why the goal here is reduction and replacement with silent pauses, not elimination.","refs":[1,2]}},{"heading":"Stress: putting the weight where the meaning is","paragraphs":["English uses stress to signal what matters. The stressed word in a phrase is slightly louder, longer and higher in pitch, and listeners use it to find the new or important information. “Mortality fell by a THIRD” tells the audience what to remember. “It was the DOSE, not the drug” uses contrastive stress to correct an assumption. Placing the stress on the wrong word, or on every word, makes speech harder to follow even when each individual sound is correct.","Word stress matters too, especially for medical terminology. Many medical terms look similar across languages but are stressed differently in English: car-di-o-my-OP-a-thy /ˌkɑː.di.əʊ.maɪˈɒp.ə.θi/, an-aes-THE-si-a /ˌæn.əsˈθiː.zi.ə/, ep-i-de-mi-OL-o-gy /ˌep.ɪ.diː.miˈɒl.ə.dʒi/. Misplaced word stress can make a familiar word hard to recognise, particularly for listeners who are themselves non-native speakers. Check the stress of your twenty most frequent technical terms in a good dictionary and practise them in full sentences, not in isolation."],"callout":{"kind":"evidence","text":"Studies of second-language speech have found that correctly placed sentence stress improved listeners’ recall and their evaluations of the speaker, and that misplaced word stress can reduce intelligibility, especially when the stress shifts to a later syllable.","refs":[3,4]}},{"heading":"Numbers and data","paragraphs":["Numbers are where small delivery problems become real errors. “Thirteen” and “thirty”, “fifteen” and “fifty” differ mainly in stress and in the final sound: thir-TEEN and fif-TEEN are stressed on the second syllable when said on their own, THIR-ty and FIF-ty on the first. Said quickly in a large room, they are easily confused.","Protect your critical numbers in four ways. Show them on the slide. Say them slowly, with a pause before them. Restate them in another form: “fifteen per cent — roughly one patient in seven”. And when you present a graph, tell the audience where to look, pause while they look, and then state the conclusion. The sequence “look, pause, conclude” prevents the audience from reading one part of the slide while you describe another."],"callout":{"kind":"recommendation","text":"Before each talk, underline every number in your notes and decide how you will say it and whether you will restate it."}},{"heading":"Marking your script","paragraphs":["The practical tool that brings these elements together is a marked script. Take the critical passages of your talk — the opening, the key result and the conclusion — and mark them by hand. Use a slash for a short pause between thought groups, a double slash for a deliberate pause, and capital letters for the one word in each phrase that carries the main stress. Then read the passage aloud twice: once naturally and once following your marks. Record both readings and listen to the difference.","You will not script the whole talk this way. The aim is to train your ear and your habits on the passages that matter most, so that pacing and emphasis become automatic in the rest of the talk."]}],"examples":[{"title":"Before and after: a results sentence","setting":"Internal medicine congress, results slide","text":"Before: “So um we found that the readmission rate was lower in the intervention group which was quite interesting and also the length of stay was shorter.” After: “In the intervention group, // readmissions fell / by a THIRD. // [pause] And patients went home / a DAY earlier.” The revised version has two thought groups per idea, a pause before and after the main result, and one stressed word in each phrase. It takes slightly longer to say, and it is remembered."},{"title":"Fifteen or fifty?","setting":"Multidisciplinary team meeting, online","text":"A registrar reports that a patient’s creatinine “went up by fifteen”. A colleague on a poor connection hears “fifty” and suggests urgent nephrology review. The discussion takes several minutes to untangle. Afterwards, the team agrees a simple habit for critical numbers: say the number, then restate it — “fifteen, one-five” — or show it in the shared document."},{"title":"Guiding the eye on a graph","setting":"Oncology grand round, Kaplan–Meier curve","text":"Instead of describing the curve while the audience is still reading the axes, the speaker says: “This is overall survival. Please look at the two lines after twelve months.” She pauses for three seconds. “They separate — and they stay separate.” She pauses again. “That is the main finding of this study.” The audience looks where she directs them, has time to see the effect, and hears the conclusion only once they are ready for it."}],"phrase_bank":[{"phrase":"The key finding is this:","use":"Introducing your main result","register":"Neutral – formal","pronunciation":"Pause after “this”; stress “KEY”.","example":"The key finding is this: // readmissions fell by a third."},{"phrase":"Let me pause here, because this matters.","use":"Signalling an important point explicitly","register":"Neutral","example":"Let me pause here, because this matters for every surgical ward."},{"phrase":"If you look at the left-hand panel, …","use":"Directing attention on a slide","register":"Neutral","pronunciation":"British usage: “left-hand panel”.","example":"If you look at the left-hand panel, you can see the control group."},{"phrase":"Notice what happens after…","use":"Guiding the eye to a change in data","register":"Neutral","example":"Notice what happens after twelve months."},{"phrase":"This is the number to remember:","use":"Protecting a critical number","register":"Neutral","example":"This is the number to remember: // fifteen per cent."},{"phrase":"That’s roughly one patient in…","use":"Restating a percentage in a concrete form","register":"Neutral","pronunciation":"“Roughly”: RUFF-lee.","example":"Fifteen per cent — that’s roughly one patient in seven."},{"phrase":"Put simply, …","use":"Summarising a complex point","register":"Neutral","example":"Put simply, the earlier we screened, the earlier we treated."},{"phrase":"To put that in context, …","use":"Comparing a result with something familiar","register":"Neutral – formal","example":"To put that in context, it’s similar to the effect of the current standard treatment."},{"phrase":"I’ll say that again, because it’s important:","use":"Deliberate repetition of a key message","register":"Neutral","example":"I’ll say that again, because it’s important: the effect was seen only after twelve months."},{"phrase":"So, to summarise this slide, …","use":"Closing a data slide before moving on","register":"Neutral","example":"So, to summarise this slide, the benefit was largest in older patients."},{"phrase":"Not the drug — the DOSE.","use":"Contrastive stress to correct an assumption","register":"Neutral, spoken","pronunciation":"Stress falls on the contrasted word.","example":"What mattered was not the drug — it was the DOSE."}],"phrase_practice":"Choose the most important data slide in your next talk. Script it with three of these expressions: one to direct the eye, one to introduce the result, and one to summarise. Mark pauses and stress, then rehearse the slide aloud three times.","demonstration":"The sample video currently shows only how captions and playback speed work in the lesson player. The instructor recording will deliver the same results passage at three speeds (fast, rushed and controlled), demonstrate thought groups, and contrast fifteen/fifty and thirteen/thirty.","mistakes":[{"mistake":"Speeding up when time is short","correction":"Cut a slide; keep your pace."},{"mistake":"Filling every silence with “um” or “so”","correction":"Notice where fillers cluster and replace them with silent pauses there."},{"mistake":"Stressing every word, so nothing stands out","correction":"Choose one stressed word per thought group."},{"mistake":"Pausing in the middle of a technical term or phrase","correction":"Pause between thought groups, not inside them."},{"mistake":"Describing a graph while the audience is still reading it","correction":"Direct the eye, pause, then conclude."},{"mistake":"Saying critical numbers quickly","correction":"Show, slow down, and restate them in another form."}],"reflection":["Where in your talks do you tend to speed up?","Which sentence in your next presentation most deserves a pause before it?","Which numbers in your current work could be misheard, and how will you protect them?"],"references":["Clark, H. H., & Fox Tree, J. E. (2002). Using uh and um in spontaneous speaking. Cognition, 84(1), 73–111.","Fox Tree, J. E. (2001). Listeners’ uses of um and uh in speech comprehension. Memory & Cognition, 29(2), 320–326.","Hahn, L. D. (2004). Primary stress and intelligibility: Research to motivate the teaching of suprasegmentals. TESOL Quarterly, 38(2), 201–223.","Field, J. (2005). Intelligibility and the listener: The role of lexical stress. TESOL Quarterly, 39(3), 399–423."]}'::jsonb, '{"title":"Mark and measure a passage","instructions":"Apply thought groups, pauses and stress to a real passage from one of your talks.","steps":["Choose a 60–100-word passage that contains a key result or a number.","Mark short pauses with / and deliberate pauses with //.","Capitalise the one word per thought group that carries the main stress.","Read it aloud twice — naturally, then following your marks — and time both readings.","Calculate your words per minute for each reading and note one difference you heard."],"prompt":"Paste your marked passage, your two timings or rates, and the difference you noticed.","min_chars":250,"model_answer":"Marked passage (49 words): “We included / four HUNDRED patients / over sixty-FIVE. // In the intervention group, / readmissions fell / by a THIRD. // [pause] That’s roughly / one patient in THREE / who didn’t come BACK. // The effect / was LARGEST / in patients / living ALONE. // So, to summarise this slide, / earlier follow-up / helped MOST / where support at home / was WEAKEST.”\n\nReading 1 (natural): 17 seconds → about 173 words per minute (49 ÷ 17 × 60). Reading 2 (marked): 22 seconds → about 134 words per minute.\nDifference: in the second reading, “by a third” sounded like the main point, and I no longer said “so” before every sentence.","self_check":["Pauses fall between thought groups, never inside a term or phrase.","There is one capitalised word per thought group, not several.","There is a deliberate pause before and after the key result.","Numbers are protected (slowed, restated or both).","You calculated both rates and described an audible difference."]}'::jsonb, '{"title":"Pace and emphasis report","brief":"Prepare a marked script of the most important data slide in one of your talks (opening sentence, key result and summary), using the marking system from this lesson. Then write a short report (200–350 words): your natural and marked speaking rates, where your fillers clustered, how you protected the numbers, and what you will change in your next presentation. In Stage 4, you will be able to record this passage in the Speaking Studio for automatic analysis.","min_words":200,"required":true,"criteria":[{"criterion":"Marking","description":"Pauses and stress are marked consistently and placed between thought groups."},{"criterion":"Measurement","description":"Speaking rates are calculated from real timings, not estimated."},{"criterion":"Data delivery","description":"Critical numbers are protected by showing, slowing or restating."},{"criterion":"Reflection","description":"Concrete changes are proposed for a specific upcoming talk."}]}'::jsonb, '/media/sample/l07-sample.mp4', '/media/sample/l07-sample.vtt', 'Sample video for demonstrating the player. The instructor recording for this lesson has not been produced yet.' from public.lessons where code = 'L07'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L07');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Where is a deliberate pause most effective?', array['Before and after a key result', 'In the middle of a technical term', 'Only at the end of the talk', 'After every word']::text[], 0, 'Pausing around key results creates attention and gives the audience time to absorb them.' from public.lessons where code = 'L07';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'The chair shows you a two-minute warning and you still have four slides. What should you do?', array['Speak faster to cover all four slides', 'Skip to your planned conclusion and keep your pace', 'Ignore the warning', 'Remove all pauses']::text[], 1, 'Cutting content protects comprehension. Speaking faster sacrifices it and usually increases errors.' from public.lessons where code = 'L07';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'What does research suggest about “um” and “uh”?', array['They are always grammatical errors', 'They can signal upcoming delays, and listeners make use of them', 'Native speakers never use them', 'They should be eliminated completely']::text[], 1, 'Fillers are a normal feature of speech. In presentations, the aim is to reduce them by using silent pauses, not to eliminate them entirely.' from public.lessons where code = 'L07';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'How many stressed words should a thought group usually carry?', array['None', 'One', 'Every noun', 'As many as possible']::text[], 1, 'One main stress per thought group tells the audience where the important information is.' from public.lessons where code = 'L07';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'You need to report that 15% of patients had a complication. Which delivery is safest for an international audience?', array['Say “fifteen per cent” quickly and move on', 'Show 15% on the slide, pause, say “fifteen per cent” slowly, and add “roughly one patient in seven”', 'Say “about fifty per cent” to simplify', 'Avoid mentioning the number']::text[], 1, 'Fifteen and fifty are easily confused. Showing, slowing and restating protects critical numbers.' from public.lessons where code = 'L07';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'You show a complex Kaplan–Meier curve. What should you do first?', array['Explain the statistical method in detail', 'Read every number on the axes', 'Tell the audience where to look, pause, then state the conclusion', 'Move quickly to the next slide']::text[], 2, '“Look, pause, conclude” prevents the audience from reading one part of the slide while you describe another.' from public.lessons where code = 'L07';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L07');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L07 Lesson handout', 'Marking system, pace calculation, number-delivery checklist and phrase bank.', '/materials/lessons/L07-handout.pdf', false from public.lessons where code = 'L07';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L08', 'lesson', 'l08-voice-projection-and-vocal-variety', 'Voice Projection and Vocal Variety', 'Breath support, resonance and intonation to avoid a monotone delivery.', 60, 3, 2, false, 'not_recorded', 'ready', 'voice-coach' from public.modules where number = 3
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Your voice carries your expertise to the back of the room. If listeners cannot hear the end of your sentences, or if every sentence sounds the same, even excellent content becomes hard to follow and easy to forget. Many second-language speakers, concentrating on words and grammar, let their voice fade, flatten or rise in ways they do not intend. This lesson is about using your voice deliberately: projecting it without strain, using intonation to signal certainty, contrast and continuation, and varying pitch, volume and pace so that the audience can hear what matters. Your accent is not the target of this lesson. The aim is a voice that is easy to hear, easy to follow and recognisably yours.","objectives":["Project your voice to the back of a room, or into a microphone, without strain","Use falling intonation to make statements and conclusions sound certain, and rising tones deliberately for questions and unfinished lists","Vary pitch, volume and pace to highlight key information and avoid a monotone delivery","Use a two-minute voice warm-up and basic voice-care habits on long speaking days"],"sections":[{"heading":"Why the voice matters for comprehension and authority","paragraphs":["Audiences use the voice for two things at once. They use it to decode the words, which requires that the words are audible and clearly separated. They also use it to interpret meaning: which information is new, which is important, whether the speaker is certain or tentative, and whether a sentence has finished. In English much of this second layer is carried by intonation and stress rather than by vocabulary.","Speaking in a second language makes both layers vulnerable. Attention spent on formulation is attention not spent on breath and volume, so the voice often fades towards the end of a sentence — exactly where English tends to place new information. The intonation patterns of your first language may also carry over into English, sometimes producing a flatter melody or rises where an English-speaking listener expects a fall. None of this is a matter of accent. A speaker with a strong accent and a well-used voice is easier to follow than a speaker with a mild accent and a monotone."],"callout":{"kind":"evidence","text":"In a study of oral presentations given in English by second-language speakers, the amount of pitch variation measured in the speakers’ voices was associated with how lively listeners judged the presentations to be.","refs":[1]}},{"heading":"Breath support and projection","paragraphs":["Projection is not shouting. A projected voice is supported by breath from the lower ribs and abdomen and directed towards the furthest listener; a shouted voice is pushed from the throat, sounds strained and tires quickly. Stand with your weight even, your shoulders relaxed and your head level. Breathe in low and quietly, so that your lower ribs widen, and let the sound ride on a steady outflow of air.","Aim your voice at the back wall, not at the first row or at your notes. The easiest check is to imagine a colleague sitting in the last row who needs to hear the final word of each sentence. Plan your breathing around your thought groups from Lesson 7: take a breath at every pause, so that you never start an important sentence with an empty chest. A sentence that runs out of air drops in volume at its most important point."],"callout":{"kind":"recommendation","text":"Before a talk in an unfamiliar room, ask a colleague to sit in the back row while you say your first two sentences. Adjust until they can hear the last word of each sentence without effort."}},{"heading":"Working with a microphone","paragraphs":["A microphone solves volume, not clarity. It amplifies whatever reaches it, including mumbling and fading sentence endings, and it punishes inconsistency. With a fixed lectern microphone, keep a constant distance of roughly a hand’s width and remember that turning your head to the screen takes your voice out of range. With a lapel microphone, clip it at the centre of the chest, about a hand’s width below the chin, on the side you are less likely to turn away from. With a handheld microphone, hold it below the mouth at a steady angle rather than waving it while you gesture.","The most common problem at congresses is speaking to the slide. If you need to point at the screen, use a simple sequence: turn to the slide and look, then turn back to the audience before you speak. Your voice stays with the microphone and the audience sees your face when they hear the key point."]},{"heading":"Intonation: falls, rises and what they signal","paragraphs":["In standard British English, a falling tone at the end of a statement signals that the statement is complete and that the speaker stands behind it: “Mortality fell by a third.↘” Conclusions, recommendations and key results need a clear fall. A rising tone at the end of a statement can be heard by many listeners as uncertainty or as an invitation to respond. It is not wrong, and in some varieties of English it is common, but in a results presentation it can make firm findings sound tentative.","Rises have important legitimate uses. Yes/no questions often rise: “Did the effect persist?↗” In a list, each item before the last usually rises to show that more is coming, and the last item falls: “We measured mortality,↗ readmissions,↗ and length of stay.↘” A fall–rise on a single word signals a reservation or an unspoken “but”: “The results were encouraging — in the short term.↘↗” Used deliberately, these patterns let you add meaning without adding words."],"callout":{"kind":"recommendation","text":"Mark the final word of every key sentence in your script with ↘ and rehearse it with a clear fall. Use ↗ only where you intend a question, an unfinished list or a reservation."}},{"heading":"Vocal variety: pitch, volume and pace","paragraphs":["Monotone delivery usually has a simple cause: reading. When attention is on the written text, pitch, volume and pace settle into a single level. Variety returns when you speak to people about ideas. Use it purposefully. Lower your pitch slightly and slow down for a key message. Increase energy and pace a little for a story or a familiar step. Drop your volume, not just raise it, to draw attention: a quieter sentence after a louder passage makes a room lean in.","Variety should serve meaning, not decoration. Exaggerated, sing-song intonation sounds artificial and can be as distracting as a monotone. The aim is a range that matches the content: a calm, confident baseline, with clear peaks on the words that carry new or important information. Second-language speakers often find that once their script is marked for stress and falls, variety follows naturally."]},{"heading":"Voice care on long speaking days","paragraphs":["Congress days, teaching blocks and on-call shifts place real demands on the voice. Keep water within reach and sip it at section breaks. Avoid repeated throat clearing; a swallow or a sip is gentler. Speak at a comfortable pitch rather than forcing a lower or louder voice than your natural one. Use the microphone when one is offered, even in a mid-sized room.","A short warm-up before speaking prepares the voice in the same way a warm-up prepares any physical skill. It also gives you a structured task in the anxious minutes before a talk, which links it to your routine from Lesson 2. Persistent hoarseness or voice change is a clinical matter that deserves assessment like any other symptom; the techniques in this lesson are educational and do not replace it.","The Academy’s two-minute warm-up has five steps, and none of them needs to be visible to colleagues in a corridor. First, release the shoulders and take three slow, low breaths. Second, hum gently on “mm”, gliding from a low to a comfortable high note and back. Third, do a few lip trills or slides on “ng” to free the voice without strain. Fourth, say two of your own difficult phrases slowly and precisely, such as the title of your talk and a key technical term. Finally, count from one to ten, aiming each number at an imaginary back wall, with a clear fall on “ten”."],"callout":{"kind":"evidence","text":"A large survey found that voice disorders were reported considerably more often by teachers than by the general population, which illustrates the load that intensive professional speaking places on the voice.","refs":[2]}}],"examples":[{"title":"The disappearing last word","setting":"International cardiology congress, auditorium for 800","text":"A cardiologist presents a trial with a clear message: “Early treatment reduced hospital admissions by a quarter.” In the back rows, colleagues hear “Early treatment reduced hospital admissions by a…”. His voice falls away on the final words, which carry the result. In rehearsal, a colleague in the last row raises a hand every time a sentence ending is lost. He adds a breath before each key sentence, aims at the back wall and gives “by a QUARTER↘” a clear stress and fall. His content and his accent are unchanged; his result now reaches the whole room."},{"title":"Findings that sounded like questions","setting":"Research meeting, early-career pathologist presenting a validation study","text":"Each of her result statements ends with a rise: “Sensitivity was ninety-two per cent?↗ Specificity was eighty-eight?↗” Her supervisor notes that the audience began to ask whether she trusted her own data. Rehearsing with falling tones — “Sensitivity was ninety-two per cent.↘ Specificity was eighty-eight.↘” — she keeps rises for her list of next steps and for one genuine question to the audience. The same numbers now sound like findings."},{"title":"Turning away from the microphone","setting":"Grand round, lecture theatre with a fixed lectern microphone","text":"A respiratory physician explains a CT image while looking at the projection screen. Each time he turns, his voice drops out of the microphone range and the recording of the session has gaps exactly where the findings are described. Using the sequence “turn and look, turn back, then speak”, he points to the image in silence, faces the audience and describes the finding. The pauses also give the audience time to look at the image, as recommended in Lesson 7."}],"phrase_bank":[{"phrase":"Can you all hear me at the back?","use":"Checking audibility at the start, especially without a microphone","register":"Neutral","pronunciation":"Fall on “BACK↘”; it is a real question but a confident one.","example":"Good morning. Can you all hear me at the back? Thank you."},{"phrase":"Let me move a little closer to the microphone.","use":"Correcting volume or distance during a talk","register":"Neutral","example":"Let me move a little closer to the microphone — is that better?"},{"phrase":"The key message is simple:","use":"Signalling a key point before delivering it with a clear fall","register":"Neutral","pronunciation":"Pause after “simple”, then lower the pitch slightly for the message.","example":"The key message is simple: // earlier screening saves time."},{"phrase":"There are three reasons: first…, second…, and third…","use":"Organising a list so the audience hears where it ends","register":"Neutral","pronunciation":"Rise on each item before the last (↗ ↗), fall on the last (↘).","example":"There are three reasons: cost,↗ access,↗ and staff time.↘"},{"phrase":"Was this effect real? We think it was.","use":"A rhetorical question followed by a firm answer","register":"Neutral, spoken","pronunciation":"Rise on the question, clear fall on the answer.","example":"Was this effect real?↗ // We think it was.↘ Here is why."},{"phrase":"The results were encouraging — in the short term.","use":"Signalling a reservation without an extra sentence","register":"Neutral – formal","pronunciation":"Fall–rise on “short TERM” (↘↗).","example":"The results were encouraging — in the short term. Long-term data are still awaited."},{"phrase":"Let me slow down here, because this matters.","use":"Announcing a deliberate change of pace","register":"Neutral","example":"Let me slow down here, because this matters for every surgical ward."},{"phrase":"Just to be clear, …","use":"Restating a key point with emphasis","register":"Neutral","example":"Just to be clear, this was not a randomised trial."},{"phrase":"Excuse me a moment.","use":"Pausing to drink water or clear your voice politely","register":"Neutral, British usage","example":"Excuse me a moment. [sip] So, the second finding…"},{"phrase":"Now, here’s what happened next.","use":"Lifting energy and pace before a story or turning point","register":"Informal – neutral","pronunciation":"Slightly higher pitch and faster pace than the preceding sentence.","example":"Now, here’s what happened next: the ward ran out of beds."}],"phrase_practice":"Choose the most important minute of your next talk. Mark every sentence ending with ↘ or ↗, insert one list with rise–rise–fall, and one sentence where you deliberately slow down and lower your pitch. Record it from across the room and listen for the last word of each sentence.","demonstration":"The instructor video shows one key-result sentence delivered three ways — monotone, exaggerated and purposeful — followed by the same passage recorded from the back of a lecture theatre with and without breath support. It ends with a two-minute voice warm-up you can follow.","mistakes":[{"mistake":"Letting the voice fade at the end of sentences","correction":"Breathe at each pause and aim the final word at the back wall."},{"mistake":"Rising intonation on findings and conclusions","correction":"Use a clear fall (↘) on statements you stand behind; keep rises for questions and unfinished lists."},{"mistake":"Pushing volume from the throat","correction":"Support the voice with low breathing; project, do not shout."},{"mistake":"Turning to the screen while speaking into a fixed microphone","correction":"Turn and look in silence, turn back, then speak."},{"mistake":"Adding ‘variety’ by exaggerating every sentence","correction":"Keep a calm baseline and place peaks only on new or important information."},{"mistake":"Clearing the throat repeatedly","correction":"Swallow or take a sip of water instead."}],"reflection":["Where in your talks does your voice tend to fade or flatten?","Which of your key sentences needs a clearer fall?","What would a two-minute warm-up look like on the morning of your next presentation?"],"references":["Hincks, R. (2005). Measures and perceptions of liveliness in student oral presentation speech: A proposal for an automatic feedback mechanism. System, 33(4), 575–591.","Roy, N., Merrill, R. M., Thibeault, S., Parsa, R. A., Gray, S. D., & Smith, E. M. (2004). Prevalence of voice disorders in teachers and the general population. Journal of Speech, Language, and Hearing Research, 47(2), 281–293."]}'::jsonb, '{"title":"One sentence, three deliveries","instructions":"Work on projection and intonation using the key-result sentence of a talk you are preparing.","steps":["Choose the sentence that carries your main result or recommendation.","Mark the stressed word and the final tone (↘ or ↗) on your script.","Record the sentence three times: monotone, exaggerated, and purposeful (calm baseline, clear stress, falling end).","Place your phone or laptop at the far side of the room and record the purposeful version again with breath support.","Listen to all four recordings and note what changed between them."],"prompt":"Write your marked sentence and describe what you heard in the four recordings (at least 250 characters).","min_chars":250,"model_answer":"Marked sentence: “In our unit, // nurse-led triage cut the time to ANALGESIA ↘ // by almost an HOUR.↘”\n\nMonotone: every word at the same level; “hour” was almost inaudible. Exaggerated: sounded like a sales presentation; my colleague laughed. Purposeful: “analgesia” and “hour” stood out and the sentence sounded finished. From across the room without breath support, the last two words disappeared; with a breath before the sentence and aiming at the wall, “by almost an hour” was clear. I also noticed that I raised my pitch on “hour” in the first attempt, which made the result sound like a question.","self_check":["One main stressed word per thought group is marked.","The final word of the key sentence has a clear fall in the purposeful version.","The far-side recording is audible to the last word.","Your description refers to what you actually heard, not to what you intended."]}'::jsonb, '{"title":"Voice plan for your next talk","brief":"Prepare the opening and the key-result section of a talk you will give (no more than 150 words of script), marked with thought groups, stressed words and final tones. Record it from across a room. Then write a voice plan of 200–350 words: what your recording showed about audibility and intonation, the three changes you made, the warm-up you will use on the day, and how you will check audibility in the venue. Do not include patient-identifiable information.","min_words":200,"required":true,"criteria":[{"criterion":"Audibility","description":"The recording and plan show that sentence endings and key words reach the furthest listener."},{"criterion":"Intonation for meaning","description":"Falls, rises and lists are marked where they carry meaning, not decoratively."},{"criterion":"Purposeful variety","description":"Changes in pace, pitch or volume are tied to specific moments in the content."},{"criterion":"Practicality","description":"The warm-up and venue check are specific and realistic for the event."}]}'::jsonb, null, null, null from public.lessons where code = 'L08'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L08');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Which statement about projection is correct?', array['Projection means speaking as loudly as possible', 'Projection relies on breath support and direction, not throat effort', 'Projection is unnecessary when a microphone is available', 'Projection requires lowering your natural pitch']::text[], 1, 'A projected voice is supported by breath and aimed at the furthest listener. Pushing from the throat causes strain.' from public.lessons where code = 'L08';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'In standard British English, what does a clear fall at the end of a statement usually signal?', array['Uncertainty', 'That the speaker expects an answer', 'That the statement is complete and the speaker stands behind it', 'That more items will follow']::text[], 2, 'Falling tones mark completion and certainty, which is why conclusions and key results benefit from a clear fall.' from public.lessons where code = 'L08';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You present three outcomes: mortality, readmissions and length of stay. Which intonation helps the audience hear where the list ends?', array['Fall on every item', 'Rise on every item', 'Rise on the first two items and fall on the last', 'Monotone throughout to sound neutral']::text[], 2, 'Rises on non-final items signal that more is coming; the fall on the last item signals the end of the list.' from public.lessons where code = 'L08';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'During a grand round with a fixed lectern microphone you need to show a detail on the CT image. What is the best approach?', array['Describe the image while facing the screen', 'Turn and look at the image in silence, turn back to the audience, then speak', 'Remove the microphone and walk to the screen', 'Ask the audience to read the slide themselves']::text[], 1, 'Speaking only when facing the audience keeps your voice in range of the microphone and gives listeners time to look at the image.' from public.lessons where code = 'L08';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'A colleague says your talk sounded “flat”. Your accent is strong. What is the most useful first step?', array['Try to reduce your accent', 'Mark stress and final tones on your key sentences and rehearse speaking to people rather than reading', 'Speak much faster to sound more energetic', 'Add a dramatic rise to every sentence']::text[], 1, 'Flat delivery usually comes from reading and unmarked stress and intonation, not from accent. Purposeful variation restores interest.' from public.lessons where code = 'L08';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'Which habit protects the voice on a long congress day?', array['Clearing the throat before each talk', 'Forcing a deeper voice for authority', 'Sipping water at breaks and using the microphone when offered', 'Avoiding any warm-up']::text[], 2, 'Hydration, a comfortable pitch, avoiding throat clearing and using amplification reduce vocal load.' from public.lessons where code = 'L08';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L08');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L08 Lesson handout', 'Projection checklist, intonation marking key, microphone guide, two-minute warm-up and phrase bank.', '/materials/lessons/L08-handout.pdf', false from public.lessons where code = 'L08';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L09', 'lesson', 'l09-body-language-and-presence', 'Body Language and Presence', 'Stance, movement, gesture and eye contact on stage, at the lectern and on camera.', 55, 3, 3, false, 'not_recorded', 'ready', 'voice-coach' from public.modules where number = 3
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Before you say your first sentence, the audience has already formed an impression from how you walk to the lectern, where you look and what your hands are doing. For second-language speakers, physical presence can be a powerful ally: a calm stance, steady eye contact and purposeful gestures signal confidence even when you are searching for a word. They can also work against you, when the effort of speaking English pulls your eyes to the slides and your hands to the clicker. This lesson treats body language as a set of practical, learnable habits rather than a performance. You will work on your stance and the first five seconds, eye contact across a room and through a camera, gestures that support your structure, and the use of space, lectern and screen in person and online.","objectives":["Establish a stable, open stance and a deliberate start in the first five seconds","Use eye contact that includes the whole audience, or the camera lens online","Use purposeful gestures that support structure and meaning, and reduce distracting movement","Manage space, lectern, slides and clicker in person, online and in hybrid sessions"],"sections":[{"heading":"What audiences read from your body — and what they do not","paragraphs":["Audiences form impressions quickly, and nonverbal behaviour contributes to them. A speaker who looks at the audience, stands steadily and moves with purpose is more likely to be perceived as prepared and credible than one who reads from the screen and sways behind the lectern, before either has said anything substantive. This is one reason why the first minute of a talk deserves rehearsal.","Two popular claims deserve caution. The first is that “93 per cent of communication is nonverbal”. This figure is a misreading of experiments from the 1960s that asked listeners to judge a speaker’s feelings from single words spoken in different tones of voice; it does not describe how audiences understand a scientific presentation, where content is essential. The second is that adopting a “power pose” for two minutes changes your hormone levels and makes you more confident. A large replication study did not find the hormonal effects. A stable, open posture is still worth practising, but for simpler reasons: it supports breathing and projection (Lesson 8), it reduces distracting movement, and it is perceived as calm.","Body language is also cultural. Norms for eye contact, distance and gesture vary between countries and between specialties. At international meetings, the most reliable strategy is moderate and readable: steady eye contact without staring, open gestures within the width of your body, and stillness when you deliver key information."],"callout":{"kind":"evidence","text":"In a well-known study, observers’ ratings of teachers based on very short silent video clips were related to end-of-term student evaluations. The often-quoted “7–38–55” rule comes from experiments on judging attitudes from single words and should not be applied to presentations. A large replication of “power posing” found no effect on hormones.","refs":[1,2,3]}},{"heading":"Stance and the first five seconds","paragraphs":["A grounded stance is simple: feet roughly hip-width apart, weight evenly distributed, knees soft rather than locked, shoulders relaxed and hands resting at about waist height or loosely by your sides. From this neutral position you can move, gesture and breathe freely. Common habits under pressure — shifting weight from foot to foot, crossing the legs, gripping the lectern or putting hands in pockets — are rarely noticed by the speaker but are very visible to the audience.","The first five seconds follow the routine from Lesson 2: arrive, place your notes, stand in your neutral position, look at the audience, breathe, and only then begin. Starting to speak while still walking, or while looking down at the laptop, makes the opening sound rushed and hides your face at the moment the audience is forming its first impression. The pause will feel long to you and look composed to everyone else."],"callout":{"kind":"recommendation","text":"Rehearse your entrance, not just your opening sentence: walk to the lectern, find your stance, look up and breathe before the first word. Two or three rehearsals are usually enough to make it automatic."}},{"heading":"Eye contact in a room and through a lens","paragraphs":["Eye contact tells listeners that you are speaking to them rather than reciting. In a large room, divide the audience mentally into sections — front left, back centre, back right, and so on — and move your gaze between them, holding it with one person for roughly the length of a thought group before moving on. This includes the back and the edges of the room, which speakers tend to forget.","Notes and slides compete for your eyes, especially when you speak in a second language. Use a simple sequence: glance down to collect the next phrase, look up, and then speak. Speaking while reading pulls the voice down into the lectern and the eyes away from the audience; collecting the phrase first and delivering it to a person keeps both. With slides, the same rule applies: look at the screen to check, then turn back before you talk.","Online, the audience experiences eye contact only when you look into the lens. Raise the camera to eye level, place your notes or speaker view just below it, and look into the lens for your opening, your key messages and your conclusion. It is unnatural to look at the lens all the time, and unnecessary; the moments that matter most are the ones to aim for."]},{"heading":"Gestures that carry meaning","paragraphs":["Gestures are not decoration. When they are linked to what you are saying, they help listeners follow you and can help you find your words. Useful presentation gestures are few and easy to learn: counting on your fingers as you enumerate points; showing two sides with two hands when you contrast; a horizontal sweep for a timeline; and an open palm towards the screen when you direct attention to a figure. Keep most gestures within the width of your body and at roughly waist-to-chest height, where they are visible but calm.","Equally important is stillness. Deliver your key message with your hands still and your body facing the audience. Movement just before a key point and stillness during it is a pattern audiences read as emphasis. Distracting movements — clicking the pen, playing with the clicker, adjusting glasses or touching the face — usually increase under stress; noticing your own two or three habits in a recording is the first step to reducing them."],"callout":{"kind":"evidence","text":"A meta-analysis of studies on gesture and comprehension found that gestures had an overall moderate benefit for listeners’ understanding, with larger effects for gestures depicting physical actions and when gestures were not completely redundant with the words.","refs":[4]}},{"heading":"Space, lectern, slides and clicker","paragraphs":["If the room allows it, step away from the lectern for parts of your talk, such as the opening, a story or the conclusion. Move with purpose: walk during transitions between sections and stand still when you make a point. Stand to the side of the screen rather than in front of the projector, ideally on the side that lets you face the audience while gesturing towards the slide.","Use the laser pointer sparingly. A shaking dot draws attention to nervous hands; a slow circle around a feature, held still, does not. Better still, build the emphasis into the slide with a highlight or an arrow, so that you can face the audience. Test the clicker in advance and hold it in your less expressive hand, so that your other hand is free for gestures."]},{"heading":"Presence online and in hybrid sessions","paragraphs":["On a video call, your presence is limited to a small frame, so details matter. Place the camera at eye level, sit or stand so that your head and shoulders fill most of the frame, and position light in front of you rather than behind. Keep gestures inside the frame and a little slower than in a room, so that they are not blurred.","In hybrid sessions you have two audiences. Speak to the room for most of the time, but turn to the camera at defined moments — when you welcome online participants, for key messages and when you take their questions — and say so: “For those joining online…”. This small habit makes remote colleagues feel included and is noticed by chairs and organisers."]}],"examples":[{"title":"Talking to the screen","setting":"Neurology grand round, case presentation with MRI images","text":"A specialty trainee stands in front of the screen and describes each image while looking at it, her back half-turned to the audience. Consultants at the back begin checking their phones. In rehearsal she moves to the left of the screen, points with an open hand while silent, turns back and says: “This is the lesion — [pause] — and it is in the brainstem.” Her slides and her words are unchanged. What changed is that the audience now sees her face when she delivers the finding."},{"title":"The lectern grip","setting":"Surgical congress, eight-minute oral presentation","text":"A colorectal surgeon grips the lectern with both hands for the whole talk and sways slightly forward and back. Watching his recording, he notices that his hands never move, even when he lists three complications. In the next rehearsal he starts with his hands resting on the lectern, then releases them to count “bleeding, leak and infection” on his fingers, and returns to the neutral position for his conclusion. The swaying stops once his weight is even. Colleagues describe the second version as “more confident” without being able to say why."},{"title":"An international webinar","setting":"Online teaching session for physicians in several countries","text":"An endocrinologist presents from a laptop on her desk. The camera looks up at her from below and she spends most of the session reading her slides on the screen. A colleague suggests three changes: raise the laptop to eye level on a stack of books, move the speaker notes just below the camera, and look into the lens for the opening, each take-home message and the summary. The feedback from participants mentions, for the first time, that she seemed to be “talking to us”."}],"phrase_bank":[{"phrase":"Let me step away from the lectern for a moment.","use":"Signalling a change of position, often before a story or the conclusion","register":"Neutral","example":"Let me step away from the lectern for a moment and tell you about one patient pathway."},{"phrase":"There are three things I’d like you to notice.","use":"Introducing an enumerating gesture","register":"Neutral","pronunciation":"Show the number with your fingers as you say “three”.","example":"There are three things I’d like you to notice on this slide."},{"phrase":"On the one hand…, on the other hand…","use":"Presenting a contrast with a two-handed gesture","register":"Neutral – formal","example":"On the one hand, the drug was effective; on the other hand, adherence was poor."},{"phrase":"Let me draw your attention to…","use":"Directing the audience to part of a slide","register":"Formal","example":"Let me draw your attention to the curve on the right."},{"phrase":"If you look at the top of the slide, …","use":"Giving a precise visual reference","register":"Neutral","example":"If you look at the top of the slide, you can see the baseline values."},{"phrase":"I’ll come back to the slides in a moment.","use":"Turning attention from the screen to yourself","register":"Neutral","example":"I’ll come back to the slides in a moment — first, a question for you."},{"phrase":"For those joining online, …","use":"Including the remote audience in a hybrid session","register":"Neutral","pronunciation":"Turn to the camera as you say it.","example":"For those joining online, please put your questions in the chat."},{"phrase":"Can everyone see the screen clearly?","use":"Checking visibility in a room or online","register":"Neutral","example":"Before we start, can everyone see the screen clearly?"},{"phrase":"Let’s take a step back.","use":"Moving from detail to the bigger picture, often with a step backwards","register":"Neutral, idiomatic","example":"Let’s take a step back and look at what this means for practice."},{"phrase":"Before I move on, …","use":"Holding a still moment for a key point before a transition","register":"Neutral","example":"Before I move on, let me repeat the one number to remember."}],"phrase_practice":"Pair each expression with its movement: enumerating fingers for “three things”, two hands for a contrast, a step back for “Let’s take a step back”, a turn to the camera for “For those joining online”. Rehearse three of them standing, as part of your own talk, and record them on video.","demonstration":"The instructor video shows the same two-minute excerpt three times: behind the lectern with no movement; with distracting habits; and with a grounded stance, sectioned eye contact, enumerating and contrasting gestures and a still delivery of the key message. A short online segment demonstrates camera height, framing and looking into the lens.","mistakes":[{"mistake":"Starting to speak while still walking or looking at the laptop","correction":"Arrive, stand, look up and breathe before the first word."},{"mistake":"Reading the slides with your back to the audience","correction":"Stand beside the screen; look, turn back, then speak."},{"mistake":"Gripping the lectern or keeping hands in pockets","correction":"Use a neutral position at waist height and release your hands for purposeful gestures."},{"mistake":"Moving constantly or swaying","correction":"Move on transitions; stand still for key messages."},{"mistake":"Looking only at the front row or one friendly face","correction":"Move your gaze between sections of the room, including the back and sides."},{"mistake":"Never looking at the camera online","correction":"Look into the lens for the opening, key messages and conclusion."}],"reflection":["Which of your physical habits under pressure did you notice for the first time in a recording?","Where in your next talk will you move, and where will you stand still?","What will you change in your online set-up before your next webinar?"],"references":["Ambady, N., & Rosenthal, R. (1993). Half a minute: Predicting teacher evaluations from thin slices of nonverbal behavior and physical attractiveness. Journal of Personality and Social Psychology, 64(3), 431–441.","Mehrabian, A., & Ferris, S. R. (1967). Inference of attitudes from nonverbal communication in two channels. Journal of Consulting Psychology, 31(3), 248–252.","Ranehill, E., Dreber, A., Johannesson, M., Leiberg, S., Sul, S., & Weber, R. A. (2015). Assessing the robustness of power posing: No effect on hormones and risk tolerance in a large sample of men and women. Psychological Science, 26(5), 653–656.","Hostetter, A. B. (2011). When do gestures communicate? A meta-analysis. Psychological Bulletin, 137(2), 297–315."]}'::jsonb, '{"title":"Video audit of your presence","instructions":"Record yourself on video delivering a two-minute section of a real talk, then analyse and improve your physical delivery.","steps":["Record two minutes of a talk standing, as you would deliver it, with the camera showing your whole upper body.","Watch the recording once without sound. Note your stance, where you look, what your hands do and any repeated movements.","Choose two changes: one to add (for example, enumerating gestures or sectioned eye contact) and one to reduce (for example, swaying or clicker play).","Record the same two minutes again with the changes.","Compare the two recordings without sound and describe the difference."],"prompt":"Describe what you saw in the first recording, the two changes you chose and the difference in the second recording (at least 250 characters).","min_chars":250,"model_answer":"First recording (silent viewing): I began speaking while still looking at the laptop. My weight moved from one foot to the other about every ten seconds. I looked at the screen for most of the key-result slide, and I clicked the pen in my left hand throughout.\n\nChanges: add — look up and breathe before the first word, and count the three outcomes on my fingers; reduce — put the pen down and keep my weight even.\n\nSecond recording: the opening looks calmer because my face is visible before I speak. The swaying is almost gone. During the key result I looked at the screen once, turned back and said the number to the camera. Without sound, the second version looks like a more senior speaker, although my words were the same.","self_check":["You watched the first recording without sound.","You identified at least one habit you had not noticed before.","The two changes are specific and observable.","The comparison describes what is visible, not what you intended."]}'::jsonb, '{"title":"Presence plan for your next talk","brief":"Using your video audit, write a presence plan (200–350 words) for a specific upcoming talk. Include: your entrance and first five seconds; where you will stand in relation to the screen; your eye-contact approach (room or camera); two purposeful gestures linked to specific moments in your content; one habit you will reduce and how; and any adjustments for an online or hybrid audience.","min_words":200,"required":true,"criteria":[{"criterion":"Evidence from the audit","description":"The plan refers to specific observations from the student’s own video."},{"criterion":"Purposeful movement","description":"Gestures and movement are linked to particular points in the content, with stillness for key messages."},{"criterion":"Audience inclusion","description":"Eye contact, screen position and online or hybrid adjustments include the whole audience."},{"criterion":"Realism","description":"The plan fits the actual venue, format and the speaker’s own style."}]}'::jsonb, null, null, null from public.lessons where code = 'L09'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L09');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'What does the often-quoted “93% nonverbal” figure actually come from?', array['Studies of scientific presentations', 'Experiments on judging feelings and attitudes from single spoken words', 'A meta-analysis of conference talks', 'Research on online teaching']::text[], 1, 'The figure comes from experiments on attitudes conveyed by single words and tone of voice. It should not be applied to presentations, where content is essential.' from public.lessons where code = 'L09';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Why does the Academy recommend a stable, open stance?', array['Because two minutes of power posing reliably changes hormone levels', 'Because it supports breathing and projection, reduces distracting movement and is perceived as calm', 'Because audiences ignore everything else', 'Because it hides nervousness completely']::text[], 1, 'The hormonal claims for power posing were not replicated in a large study. The practical benefits of a stable stance remain.' from public.lessons where code = 'L09';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You need to explain an MRI finding in a grand round. Which sequence is best?', array['Stand in front of the projector and explain while looking at the image', 'Stand beside the screen, point in silence, turn back to the audience, then state the finding', 'Ask the audience to read the report on the slide', 'Use the laser pointer continuously while speaking to the screen']::text[], 1, 'Looking, turning back and then speaking keeps your face and voice with the audience at the moment the finding is delivered.' from public.lessons where code = 'L09';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'You present online to colleagues in five countries. Where should you look during your key take-home message?', array['At the slide on your screen', 'At your notes', 'Into the camera lens', 'At the participants’ thumbnails']::text[], 2, 'Online, the audience experiences eye contact only when you look into the lens. Prioritise it for the opening, key messages and conclusion.' from public.lessons where code = 'L09';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'According to research on gesture and comprehension, when do gestures help listeners most?', array['When they are constant and energetic', 'When they add information that is not completely redundant with the words', 'Only when the speaker is a native speaker', 'Never; gestures distract']::text[], 1, 'A meta-analysis found a moderate overall benefit, larger when gestures depict actions and add information beyond the words.' from public.lessons where code = 'L09';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'You are delivering your most important result. What should your body be doing?', array['Walking across the stage to add energy', 'Standing still, facing the audience, with hands calm', 'Turning to the slide to read the number', 'Using the laser pointer in rapid circles']::text[], 1, 'Movement before a key point and stillness during it is a pattern audiences read as emphasis.' from public.lessons where code = 'L09';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L09');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L09 Lesson handout', 'Stance and entrance checklist, eye-contact map, gesture set, online set-up guide and phrase bank.', '/materials/lessons/L09-handout.pdf', false from public.lessons where code = 'L09';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'W1', 'workshop', 'w1-workshop-i-voice-and-presence-lab', 'Workshop I — Voice and Presence Lab', 'Record a two-minute opening, receive AI delivery analysis, and refine pace, pausing and projection across three attempts.', 120, 3, 4, false, 'not_recorded', 'ready', 'voice-coach' from public.modules where number = 3
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"This workshop is where the skills of Modules 1–3 become habits. You will take one short extract from a real presentation of your own — the opening, the key result and the close — and deliver it three times: as you would today, after focused practice, and finally under a realistic professional disruption. Between the recordings you will work in three practice stations on pace and pausing, voice, and physical presence. Because the extract stays the same, the differences between your recordings are differences in delivery, and you will be able to see and measure them. You will finish with a clear picture of your strengths and priorities, a warm-up you can use on the day of your next talk, a plan for handling interruptions and technical problems, and a concrete action plan for a named presentation.","objectives":["Deliver a 2–3-minute conference extract (opening, key result and close) so that a listener understands the key message and numbers after one hearing","Use pauses, sentence stress and falling intonation to signal what matters, and stress your own key technical terms correctly","Project your voice with breath support and use purposeful presence: stance, eye contact, gesture and stillness","Recover from an unexpected disruption within a few seconds, using a prepared phrase, and return to your message","Compare three recordings of the same extract and identify, with evidence, your strengths and priorities","Write a specific action plan for your next real presentation"],"sections":[{"heading":"How the workshop works","paragraphs":["The workshop has eight steps after the Readiness Check: a briefing, three recording rounds and three practice stations, followed by a debrief. You can take it in two ways. In the facilitated version, a group of three works through the steps in 120 minutes, rotating the roles of speaker, timekeeper and listener. In the independent version, you work alone at your own pace, usually across three sittings of about an hour; the platform saves your progress after every step, and you can pause, repeat a station or return to an earlier step at any time.","The principle behind the design is simple. Improvement in speaking comes from focused practice on one element at a time, with feedback, rather than from repeating a whole talk until it feels familiar. Each station isolates one group of skills that you studied in L07, L08 and L09. Each recording round then puts them back together in your own material, so that you can hear what has changed."],"callout":{"kind":"evidence","text":"Research on expert performance distinguishes deliberate practice — focused effort on specific aspects of performance, with feedback — from simple repetition, and associates it with the development of expertise.","refs":[2]}},{"heading":"Choosing your extract","paragraphs":["Choose 2–3 minutes from a presentation you will actually give, or have recently given: the opening (from your L02 exercise), the slide with your key result or recommendation (from your L07 exercise), and your closing sentence. The extract should contain at least one number that matters and at least two technical terms. Write it out as you intend to say it, and keep this script for all three rounds. Use only material you are permitted to share, and never include identifiable patient information.","If you do not have a suitable talk yet — for example, if you are early in your career — use the Academy practice extract in the Workshop Pack. It is a fictional results slide written for this workshop, with the same features as a real one."]},{"heading":"How you will be assessed","paragraphs":["The workshop uses six criteria: opening and audience orientation; pace and pausing for comprehension; emphasis and intonation; accuracy and intelligibility of numbers and terminology; voice and physical presence; and composure, recovery and self-analysis. Each has three levels — Beginning, Developing and Competent — described with concrete examples in the Workshop Pack.","There are two separate statuses, and it is important not to confuse them. Workshop Completed means that you have done all the required activities — the Readiness Check, the three Practice Rounds with their logs and the stations — and submitted the written Final Task. Competent means that an instructor has observed your Round 3 performance and confirmed, using the rubric, that you meet the standard: Competent in at least five of the six criteria, including pace and pausing (criterion 2) and numbers and terminology (criterion 4), which are the core intelligibility skills. You rate yourself on the same criteria in every round. Your self-assessment is an essential learning tool, but it is your own judgement, not an independent assessment, and it never sets the Competent status.","The criteria measure communication, not performance tricks. Your accent is never penalised when your speech is intelligible. Speaking rate is recorded as diagnostic information, not as a target: the question is whether a listener can follow and report your key message after one hearing. Fillers are judged by their effect, not counted against you. And natural, credible delivery is valued above visible technique; an exaggerated pause or a theatrical gesture that makes you sound less like yourself does not score higher."],"callout":{"kind":"recommendation","text":"Use the listener comprehension check in every round. It is the most direct test of intelligibility available: a listener who hears your extract once and writes down your key message and numbers correctly has understood you."}},{"heading":"Measuring without obsessing","paragraphs":["In each round you will record a few simple measures: the length of your recording, the time and word count of your key-result segment, whether the key result was framed by pauses, where any fillers clustered, and — most importantly — the result of the comprehension check. Words per minute are calculated for you as a diagnostic aid. A rate that rises sharply under pressure, for example, tells you where to focus; it does not, on its own, tell you whether you were understood.","Measure the first take of each round. Re-recording until a lucky take appears hides the information you need. If a round goes badly, that is useful evidence; record what happened and change one thing in the next round."]},{"heading":"Your recordings and your privacy","paragraphs":["You record each round on your own phone or computer. Your recordings stay on your device: the platform does not upload, store or analyse them, and no one at the Academy can see them unless you choose to play one during a live session. The platform stores only what you type into the round logs, your self-assessment and your Final Task, and you can download all of it from Account Settings at any time.","Record only yourself. Do not record patients, colleagues or anyone else without their agreement, and keep identifiable clinical information out of your extract and your recordings. In the facilitated version, each participant records on their own device, and recordings of other participants are never kept, shared or uploaded."]},{"heading":"If you need an adjustment","paragraphs":["The workshop assumes that you can speak aloud, listen to a recording and stand. If any of these is difficult for you — for example because of a speech, hearing, voice or mobility condition, or a temporary injury — you can use an adjusted route with the same learning outcomes. You do not need to explain your reasons in detail.","Common adjustments are: delivering the extract seated; using captions or a transcript of your own recording (most phones can produce one) instead of listening back; completing the comprehension check in writing with your listener; replacing the spoken pressure card with a written recovery plan; and extra time for any step. If your voice is not available to you, you can deliver the extract using text-to-speech or another communication aid; you are then assessed on structure, emphasis planning, slide design, numbers and terminology, recovery planning and self-analysis, and the voice-dependent criteria are replaced by equivalent planning criteria agreed with the Academic Director.","To arrange an adjustment, choose “Accessibility and adjustments” on the contact form or tell your facilitator. The Academy’s Reasonable Adjustments Policy explains how requests are handled and how your information is kept confidential."]},{"heading":"Pressure, practised safely","paragraphs":["Round 3 adds a pressure card: a short, realistic disruption such as a chair’s one-minute signal, failed slides or a clarifying question about a number. You can read all the cards in the Workshop Pack in advance, so the only surprise is which card appears and when. The disruptions are professional situations that every experienced speaker meets, never personal challenges. You can choose standard cards only, or add stretch cards if you want a harder challenge, and you can repeat Round 3 with a new card as often as you wish.","Practising under mild, controlled pressure prepares you for the moment when pressure is real. The goal is not to remove the disruption but to show that you can acknowledge it briefly, use a prepared phrase, and return to your message.","The pressure element is always your choice. If a spoken disruption is not right for you at the moment, you can complete Round 3 without a card and instead write a recovery plan for two cards of your choice; this still counts towards Workshop Completed."],"callout":{"kind":"recommendation","text":"This is an Academy recommendation informed by research in skilled motor performance, where training under mild anxiety improved performance under pressure. That research did not study public speaking, so it supports the design of this workshop rather than proving its effect.","refs":[1]}}],"examples":[{"title":"Model performance 1 — from baseline to Round 3","setting":"Fictional gastroenterologist presenting a quality-improvement result","text":"Round 1: she opens with “So, this is our project about endoscopy waiting times”, delivers the key result — “waiting time fell from fourteen to nine weeks” — in the middle of a long sentence, and her listener writes down “forty to nine weeks”. Round 2: after Station A she frames the result with pauses, says “fourTEEN — one-four — to NINE weeks” with clear stress, and her listener reports it correctly. Round 3: she draws the one-minute card at 1:10, says “In the interest of time, let me go straight to the key finding”, delivers the result and the close within the minute, and keeps her pace. Her accent is unchanged across the three recordings; what changed is how easy she is to follow."},{"title":"Model performance 2 — recovering from a slide failure","setting":"Fictional cardiologist, international congress, failed projector","text":"Forty seconds in, the screen goes dark. He pauses, turns back to the audience and says: “We seem to have lost the slides, so let me describe the result instead.” He holds up three fingers — “three things happened” — and describes them, stating the critical number twice. When the slides return he says “That’s the graph I was describing” and moves on. The interruption lasts five seconds; the audience remembers the result rather than the failure."},{"title":"Model performance 3 — a data slide: look, pause, conclude","setting":"Fictional oncologist, grand round, survival curve","text":"She turns to the slide in silence and points with an open hand: “Please look at the two lines after twelve months.” She turns back, waits three seconds, and says with a clear fall: “They separate — and they stay separate.↘” Her hands are still and she looks at the back of the room. Then she restates the number in a concrete form: “That is about one additional patient in ten alive at two years.” Every element of L07, L08 and L09 is visible, and none of it looks like a technique."}],"phrase_bank":[{"phrase":"In the interest of time, let me go straight to the key finding.","use":"Responding to a time warning without speeding up","register":"Neutral – formal","pronunciation":"Pause after “finding”.","example":"In the interest of time, let me go straight to the key finding: // waiting times fell by five weeks."},{"phrase":"We seem to have lost the slides, so let me describe the result instead.","use":"Continuing calmly after a technical failure","register":"Neutral","example":"We seem to have lost the slides, so let me describe the result instead. Three things happened…"},{"phrase":"If I may, I’ll take that question at the end.","use":"Postponing an interruption politely","register":"Formal","example":"That’s an important question. If I may, I’ll take it at the end, when I show the subgroups."},{"phrase":"Let me just check — can everyone at the back hear me?","use":"Checking audibility after a microphone problem","register":"Neutral","pronunciation":"Fall on “BACK”.","example":"The microphone seems to have stopped. Let me just check — can everyone at the back hear me?"},{"phrase":"Let me bring us back to the main point.","use":"Returning to the message after a disruption","register":"Neutral","example":"Let me bring us back to the main point: earlier screening found delirium sooner."},{"phrase":"I’ll leave you with one number:","use":"Closing with a protected critical number","register":"Neutral","pronunciation":"Pause before the number; clear fall after it.","example":"I’ll leave you with one number: // nine weeks. ↘"},{"phrase":"What worked particularly well was…","use":"Opening peer feedback with a specific strength","register":"Neutral","example":"What worked particularly well was the pause before your result."},{"phrase":"At about one minute forty, the pace picked up when…","use":"Giving time-referenced, observable feedback","register":"Neutral","example":"At about one minute forty, the pace picked up when you reached the limitations."},{"phrase":"I lost the thread when…","use":"Reporting where you, as listener, stopped following","register":"Neutral, honest","example":"I lost the thread when the second number came straight after the first."},{"phrase":"One thing I’d suggest trying is…","use":"Offering one concrete change","register":"Neutral, collegial","example":"One thing I’d suggest trying is turning back to us before you say the number."},{"phrase":"Could you show me where you’d pause on this slide?","use":"Helping a speaker plan pauses","register":"Neutral","example":"Could you show me where you’d pause on this slide? Let’s mark it together."},{"phrase":"Compared with your first round, …","use":"Linking feedback to measurable change","register":"Neutral","example":"Compared with your first round, your listener got both numbers right this time."}],"phrase_practice":"Before Round 3, choose the two recovery phrases you are most likely to need and say each aloud three times in full sentences about your own topic. In the facilitated version, use the six feedback expressions when you act as listener: always give one specific strength, one observation tied to a moment in the recording, and one suggestion.","demonstration":"The instructor briefing video and the three model-performance videos have not yet been recorded; until they are, the model performances are provided as the annotated written examples above. The briefing video will introduce the workshop in about four minutes and demonstrate the listener comprehension check.","mistakes":[{"mistake":"Re-recording until you get a lucky take","correction":"Measure the first take of each round; change one thing in the next round."},{"mistake":"Changing the script between rounds","correction":"Keep the same extract, so that differences are differences in delivery."},{"mistake":"Treating words per minute as the goal","correction":"Use the comprehension check as the test; use the rate only to diagnose."},{"mistake":"Trying to fix everything at once","correction":"Choose one priority per station and per round."},{"mistake":"Over-performing the techniques","correction":"Keep pauses, gestures and intonation natural; they should serve the audience, not be noticed."},{"mistake":"Apologising when the pressure card appears","correction":"Acknowledge briefly, use your prepared phrase and return to the message."}],"reflection":["Which single change made the biggest difference to your listener’s understanding?","Which habit is still present in Round 3, and what causes it?","Which disruption are you most likely to meet in your next real presentation, and what will you say?"],"references":["Oudejans, R. R. D., & Pijpers, J. R. (2009). Training with anxiety has a positive effect on expert perceptual–motor performance under pressure. Quarterly Journal of Experimental Psychology, 62(8), 1631–1647.","Ericsson, K. A., Krampe, R. T., & Tesch-Römer, C. (1993). The role of deliberate practice in the acquisition of expert performance. Psychological Review, 100(3), 363–406."],"workshop":{"outcomes":[{"outcome":"A measurable comparison of initial and final recordings","producedIn":"Practice Rounds 1–3","evidence":"Progress sheet: comprehension-check results, pause placement, key-segment timing and fillers in context, for all three rounds"},{"outcome":"A clear understanding of individual strengths and improvement areas","producedIn":"Debrief and Final Task","evidence":"Two strengths and two priorities, each linked to a moment in the recordings"},{"outcome":"A voice and presence technique for immediate use","producedIn":"Stations B and C","evidence":"Two-minute voice and presence warm-up on the speaker card"},{"outcome":"A strategy for an interruption or technical problem","producedIn":"Station C and Round 3","evidence":"Recovery plan: likely disruption, prepared phrase and three-step recovery, tested under a pressure card"},{"outcome":"A concrete action plan for the next real presentation","producedIn":"Debrief and Final Task","evidence":"Transfer plan and one-page speaker card for a named event"}],"assessmentPrinciples":["Intelligibility, not accent. A non-native accent is never penalised. The question is whether the audience can understand and follow the message without undue effort.","Pace serves comprehension. Words per minute are diagnostic information, never a pass/fail target. Appropriate pace depends on content, room and audience.","Fillers in context. Fillers are a normal feature of speech; they matter only when their frequency or placement distracts from or obscures the message.","Natural over mechanical. Techniques are rewarded when they serve the audience; exaggerated pauses, theatrical gestures or forced intonation are not.","Audience-centred. For every criterion the question is: does this help this audience understand and trust the message?"],"completionRule":"Workshop Completed: Readiness Check passed, all three Practice Rounds logged and the written Final Task submitted. Competent (confirmed by an instructor using this rubric, never by self-assessment): Competent in at least five of the six criteria, including criterion 2 (pace and pausing for comprehension) and criterion 4 (numbers and terminology). If Competent is not yet reached, repeat Round 3 with a new pressure card and ask for reassessment; there is no limit on attempts.","competence":{"min":5,"required":[2,4]},"readinessMinutes":{"facilitated":10,"selfPaced":[10,15]},"sessions":[{"title":"Sitting 1 — Baseline and pace","steps":["briefing","round1","stationA"]},{"title":"Sitting 2 — Voice and presence","steps":["round2","stationB","stationC"]},{"title":"Sitting 3 — Performance and plan","steps":["round3","debrief"]}],"steps":[{"key":"briefing","title":"Briefing","kind":"briefing","facilitatedMinutes":10,"selfPacedMinutes":[15,15],"purpose":"Understand the method, the assessment principles and the rubric, and prepare your extract.","instructions":["Read the Briefing tab and the assessment rubric in the Workshop Pack.","Choose your 2–3-minute extract (opening, key result, close) or use the Academy practice extract.","Write out the extract as you intend to say it; underline every critical number and your two hardest technical terms.","Prepare your recording set-up: phone or laptop camera at eye level, showing your upper body, in a room where you can stand."],"selfPacedNotes":["Arrange a listener for the comprehension check if you can (a colleague, friend or family member). If not, you will use the delayed self-check described in Round 1."],"checklist":["I have read the assessment principles and the rubric","My extract is written out, with critical numbers and two key terms underlined","My recording set-up is ready"],"output":"Written extract and recording set-up","basedOn":["L02","L07"],"facilitator":{"setup":"Form groups of three. Explain the three roles (speaker, timekeeper, listener) and the rotation. Show the rubric and read the five assessment principles aloud.","observe":["Whether each participant’s extract contains a real key result and at least one critical number","Participants who have no suitable talk: offer the practice extract"],"difficulties":[{"issue":"Extract too long (over three minutes)","response":"Ask the participant to keep only the opening, one result slide and the closing sentence."},{"issue":"Participant worried about being recorded","response":"Remind them that recordings stay on their own device and that the first round is diagnostic, not assessed."}]}},{"key":"round1","title":"Round 1 — Baseline recording","kind":"round","facilitatedMinutes":15,"selfPacedMinutes":[20,25],"purpose":"Capture how you deliver the extract today, before any practice in this workshop.","instructions":["Stand, start the recording on your own device and deliver the extract once, as you would at a meeting. Do not re-record: the first take is your baseline. Your recording stays on your device; the platform stores only what you type in the log.","Comprehension check: your listener hears the extract once and writes down the key message and any numbers they heard.","Time your key-result segment and count its words (the platform calculates words per minute as diagnostic information).","Note whether you paused before and after the key result, and where any fillers clustered.","Rate yourself on the six criteria and write one thing to change in Round 2."],"selfPacedNotes":["Delayed self-check if you have no listener: wait at least an hour, play the recording once at normal speed without pausing, write down the key message and numbers, then compare with your script."],"output":"Recording 1 and its log","basedOn":["L07"],"facilitator":{"setup":"Each speaker records on their own device; the timekeeper may start and stop it only with the speaker’s agreement. Listener has paper for the comprehension check. Rotate until all three participants have recorded.","observe":["Did the listener report the key message and numbers correctly?","Where did the speaker accelerate?","Was there any apology or throat-clearing at the start?"],"difficulties":[{"issue":"Speaker wants to start again after a mistake","response":"Ask them to continue. The baseline must be a real first take."},{"issue":"Listener reports everything correctly","response":"Ask what took effort to follow; there is usually still something to improve."}]}},{"key":"stationA","title":"Station A — Pace, pause, stress, numbers and terms","kind":"station","facilitatedMinutes":20,"selfPacedMinutes":[25,35],"purpose":"Make the key result impossible to miss.","instructions":["Mark thought groups on your script with / for short pauses and // for deliberate pauses; frame the key result with // before and after.","Capitalise the one word in each thought group that carries the main stress.","Practise “look, pause, conclude” on your data slide: say where to look, pause while the audience looks, then state the conclusion.","Term-stress clinic: check your own key terms against the verified term-stress card in the Workbook; practise each in a full sentence.","Number drills: say each critical number slowly, then restate it in another form (“fifteen per cent — roughly one patient in seven”). Practise thirteen/thirty and fifteen/fifty contrasts."],"checklist":["Thought groups and pauses marked; key result framed by //","One stressed word marked per thought group","“Look, pause, conclude” rehearsed on my data slide","My key terms checked against the term-stress card","Every critical number protected (shown, slowed or restated)"],"output":"Marked script and personal term list","basedOn":["L07"],"facilitator":{"setup":"Participants work individually for 10 minutes, then read their key-result sentence to their group twice: before and after marking.","observe":["Pauses placed between, not inside, thought groups","Stress on one word per group, not every word","Numbers restated in a concrete form"],"difficulties":[{"issue":"Pauses so long they sound mechanical","response":"Ask for the same pause ‘as if waiting for a colleague to write it down’ — natural, not dramatic."},{"issue":"Unsure of a term’s stress","response":"Check the verified card or a standard British dictionary; do not guess."}]}},{"key":"round2","title":"Round 2 — Re-record and compare","kind":"round","facilitatedMinutes":10,"selfPacedMinutes":[15,15],"purpose":"Measure the effect of Station A on the same extract.","instructions":["Record the same extract once, following your marked script. First take only.","Repeat the comprehension check with a listener (or the delayed self-check).","Log the same measures as in Round 1 and compare them in the progress table.","Rate yourself again on the six criteria and note one change for Round 3."],"output":"Recording 2, its log and the Round 1–2 comparison","basedOn":["L07"],"facilitator":{"setup":"Same roles as Round 1; ideally use a different listener so the content is fresh.","observe":["Did the comprehension-check result change?","Is the delivery still natural with the new pauses?"],"difficulties":[{"issue":"Speaker sounds robotic following the marks","response":"Ask them to keep the key-result pauses and let the rest flow more naturally."}]}},{"key":"stationB","title":"Station B — Projection and vocal variety","kind":"station","facilitatedMinutes":15,"selfPacedMinutes":[20,25],"purpose":"Make your voice reach the last row and carry meaning.","instructions":["Do the five-step, two-minute voice warm-up from L08.","Room-distance test: place your recording device at the far side of the room; record your key sentence without, then with, a breath before it and your voice aimed at the back wall. Can you hear the last word in both?","Mark the final tone of each key sentence (↘ or ↗). Results and conclusions need a clear fall; use rises only for questions and unfinished lists.","Deliver your key sentence three ways — monotone, exaggerated, purposeful — and keep the purposeful version.","If you will use a microphone, rehearse “turn and look, turn back, then speak” at your data slide."],"checklist":["Voice warm-up completed","Room-distance recording: last word audible","Final tones marked on key sentences","Purposeful version of my key sentence chosen","Microphone sequence rehearsed (if relevant)"],"output":"Your two-minute warm-up and a marked key sentence","basedOn":["L08"],"facilitator":{"setup":"Use the full width of the room. The listener sits in the furthest seat and raises a hand when a sentence ending is lost.","observe":["Sentence endings at the back of the room","Rising tones on findings","Throat strain when projecting"],"difficulties":[{"issue":"Participant shouts instead of projecting","response":"Return to low breathing; ask for the same volume with less effort, aimed at the wall."},{"issue":"Exaggerated, sing-song intonation","response":"Ask for a calm baseline with peaks only on the stressed words."}]}},{"key":"stationC","title":"Station C — Presence and recovery","kind":"station","facilitatedMinutes":15,"selfPacedMinutes":[20,25],"purpose":"Look composed, include the whole audience and stay in control when something goes wrong.","instructions":["Watch Recording 2 without sound. Note stance, eye contact, hands and any repeated movement.","Rehearse your entrance: arrive, stand in your neutral position, look up, breathe, then begin.","Choose two purposeful gestures for your extract (for example enumerating and contrasting) and decide where you will be still (the key result).","Practise eye contact by sections of the room, or into the lens if you present online.","Read all the pressure cards in the Workshop Pack. Choose and rehearse two recovery phrases, and the three-step recovery from L02: pause and breathe, find your place, bridge back with a recap."],"checklist":["Silent video audit done; two habits identified","Entrance rehearsed","Two purposeful gestures and a still moment planned","Eye-contact plan for room or lens","All pressure cards read; two recovery phrases rehearsed"],"output":"Personal presence checklist and recovery plan","basedOn":["L09","L02"],"facilitator":{"setup":"Pairs watch each other’s Recording 2 without sound for two minutes, then give one strength and one observation using the feedback phrases.","observe":["Swaying or gripping the lectern","Gaze only on notes or the front row","Stillness during the key result"],"difficulties":[{"issue":"Participant feels gestures are ‘not my culture’","response":"Keep gestures small and within the body’s width; the aim is readable, not theatrical. Stillness is also a valid choice."},{"issue":"Anxiety about the pressure cards","response":"Point out that all cards can be read in advance and that Round 3 can be repeated; choose standard cards only."}]}},{"key":"round3","title":"Round 3 — Performance under pressure","kind":"round","facilitatedMinutes":15,"selfPacedMinutes":[20,20],"purpose":"Show that your delivery holds under a realistic disruption.","instructions":["Do your warm-up. Choose standard cards only, or include stretch cards.","Start your recording and the on-screen timer at the same moment, then begin. A pressure card will appear between 45 and 90 seconds in.","Respond as you would in a real session: acknowledge briefly, use a prepared phrase, return to your message, and finish.","Complete the comprehension check and log the round, including how you recovered.","Rate yourself on the six criteria. If you want another attempt, draw a new card and repeat; your best attempt is the one you submit with the Final Task."],"selfPacedNotes":["You can stop or reset the timer at any time. To try a card as practice, simply do not save the round: nothing is logged until you save."],"output":"Recording 3 (your final performance) and its log","basedOn":["L02","L07","L08","L09"],"facilitator":{"setup":"The timekeeper draws a card face down and reveals it only after the speaker has started, between 45 and 90 seconds in. The listener completes the comprehension check and the observer sheet.","observe":["The first five seconds after the disruption","Which recovery phrase was used","Whether pace returned to normal and the key message was delivered"],"difficulties":[{"issue":"Speaker freezes","response":"Wait five seconds, then say quietly: ‘Take a breath — recap your last point.’ Log it as a learning attempt and allow a repeat."},{"issue":"Speaker apologises repeatedly","response":"In feedback, model a one-line acknowledgement from the phrase bank."}]}},{"key":"debrief","title":"Debrief and transfer plan","kind":"debrief","facilitatedMinutes":10,"selfPacedMinutes":[20,25],"purpose":"Turn the evidence from three recordings into a plan for your next real presentation.","instructions":["Review the progress table across Rounds 1–3.","Answer the debrief questions.","Write your transfer plan in the Workbook: the event, two strengths, two priorities, three commitments, your warm-up and your recovery phrase.","Complete your one-page speaker card.","Write and submit the Final Task."],"checklist":["Progress table reviewed","Debrief questions answered","Transfer plan written for a named event","Speaker card completed"],"output":"Transfer plan, speaker card and Final Task","facilitator":{"setup":"Each participant shares one sentence: ‘The change that made the biggest difference for me was…’. Then individual writing time.","observe":["Plans linked to evidence from the recordings","Commitments that are specific and observable"],"difficulties":[{"issue":"Vague commitments (‘be more confident’)","response":"Ask: ‘What would I see or hear in your next talk if you did that?’"}]}}],"roundFields":[{"key":"duration","label":"Length of the recording (m:ss)","help":"For example 2:35.","type":"text"},{"key":"key_words","label":"Words in the key-result segment","help":"Count the words from your script.","type":"number"},{"key":"key_seconds","label":"Seconds for the key-result segment","help":"Time it from your recording.","type":"number"},{"key":"heard_message","label":"Key message as heard by the listener","help":"Written after one hearing, without pausing.","type":"textarea"},{"key":"heard_numbers","label":"Numbers as heard by the listener","help":"For example: 14 weeks → 9 weeks.","type":"text"},{"key":"comprehension","label":"Comprehension check result","help":"Compare with your script.","type":"choice","options":["Fully correct","Partly correct","Not correct"]},{"key":"pauses","label":"Pauses around the key result","help":"Listen to the recording.","type":"choice","options":["Before and after","Before only","After only","Neither"]},{"key":"fillers","label":"Effect of fillers","help":"Judge the effect, not the count.","type":"choice","options":["Not distracting","Distracting in places","Obscured the key message"]},{"key":"fillers_where","label":"Where fillers or hesitations clustered (if anywhere)","help":"For example: at slide transitions.","type":"text"},{"key":"recovery","label":"Recovery from the pressure card (Round 3)","help":"Leave blank in Rounds 1 and 2.","type":"choice","options":["Recovered within a few seconds with a prepared phrase","Recovered with visible strain","Did not recover yet"]},{"key":"next","label":"One thing to change next time","help":"Choose one, specific and observable.","type":"textarea"}],"pressureCards":[{"code":"P1","title":"One minute left","situation":"The chair holds up a sign: “1 minute”.","task":"Finish within 60 seconds from now, including your key message and your close, without speeding up.","recovery":"“In the interest of time, let me go straight to the key finding.” Skip to the key result; keep your pace.","intensity":"standard"},{"code":"P2","title":"Slides fail","situation":"The screen goes dark. Your slides are gone.","task":"Continue for at least 30 seconds without slides, describing your key result in words.","recovery":"“We seem to have lost the slides, so let me describe the result instead.” Use an enumerating gesture and state the number twice.","intensity":"standard"},{"code":"P3","title":"Was that fifteen or fifty?","situation":"Someone calls out: “Sorry — was that fifteen or fifty per cent?”","task":"Answer precisely, protect the number and return to where you were.","recovery":"“Fifteen — one-five — roughly one patient in seven. So, …”","intensity":"standard"},{"code":"P4","title":"Microphone stops","situation":"The microphone cuts out.","task":"Check audibility and continue to the end without amplification.","recovery":"“Let me just check — can everyone at the back hear me?” Breathe low and aim at the back wall.","intensity":"standard"},{"code":"P5","title":"Late arrivals","situation":"The door opens and a group of colleagues comes in noisily.","task":"Pause until the room settles, then resume with a short recap.","recovery":"Pause and breathe. “Let me pick up where I left off: …”","intensity":"standard"},{"code":"P6","title":"Lost your place","situation":"Look away from your notes for three seconds, as if you have lost your place.","task":"Recover using the three-step technique from L02.","recovery":"Pause and breathe; find the slide title; bridge back: “So, to recap — … Let me now turn to …”","intensity":"standard"},{"code":"P7","title":"Speak up, please","situation":"The chair says: “Could you speak up a little? People at the back can’t hear.”","task":"Adjust projection immediately and sustain it to the end.","recovery":"“Of course — is this better?” Then low breath and aim at the back wall.","intensity":"standard"},{"code":"P8","title":"Camera frozen (online)","situation":"Your video has frozen; participants can still hear you.","task":"Tell them, and continue audio-only with clear signposting.","recovery":"“It seems my video has frozen — I’ll continue with audio. I’m on the key result slide.”","intensity":"standard"},{"code":"S1","title":"Methodological challenge","situation":"A senior colleague interrupts: “Isn’t this just a single-centre observational study?”","task":"Acknowledge, answer in no more than two sentences, and return to your message.","recovery":"“That’s a fair point — it is observational, so we can’t claim causation. What it does show is…”","intensity":"stretch"},{"code":"S2","title":"Too good to be true","situation":"Someone says: “With respect, these numbers look too good to be true.”","task":"Stay calm, give one piece of supporting evidence and one limitation, then continue.","recovery":"“I understand the scepticism. The effect was consistent across both sites; the main limitation is the follow-up period. Let me show you…”","intensity":"stretch"}],"pressureGuidance":["All cards can be read in advance. The only surprises are which card appears and when.","Every card describes a professional situation that experienced speakers meet; none is personal.","Standard cards are the default. Stretch cards are optional for participants who want a harder challenge.","You can stop at any time, practise a card without logging it, and repeat Round 3 with a new card as often as you wish.","The aim is not to make the disruption disappear, but to acknowledge it briefly and return to your message."],"rubric":[{"number":1,"title":"Opening and audience orientation","mandatory":false,"question":"Does the audience know quickly why the topic matters, what the speaker will show and how the talk is organised?","evidence":"Recording, first 40 seconds","levels":{"beginning":"Opens with an apology or with detail before any purpose; no route.","developing":"Purpose stated but buried or rushed; route missing or unclear.","competent":"Context, purpose and route within about 40 seconds, at a pace the audience can absorb, without apology."},"examples":{"beginning":"“Sorry for my English. So, we included 412 patients aged over 65…”","developing":"A clear purpose sentence, then straight into data without telling the audience what is coming.","competent":"“Delirium is often missed after surgery. [pause] Today I’ll show you one change in screening that helped us find it earlier — what we changed, what we found, and what we’re still unsure about.”"}},{"number":2,"title":"Pace and pausing for comprehension","mandatory":true,"question":"Can the audience follow and absorb the content at the pace delivered?","evidence":"Comprehension check; pause placement; key-segment timing (diagnostic)","levels":{"beginning":"The key result is delivered so quickly, or so run together with surrounding sentences, that a listener cannot report it correctly after one hearing; pace increases further under pressure.","developing":"The key result is understood, but some passages are rushed or pauses fall inside phrases; pace accelerates noticeably under the pressure card; or pauses are so long and frequent that delivery becomes mechanical.","competent":"A listener reports the key message correctly after one hearing; pauses fall between thought groups and frame the key result; pace is adapted to the content; under pressure the speaker reduces content rather than speed."},"examples":{"beginning":"“Sowefoundthatwaitingtimesfellfromfourteentonineweekswhichwasquiteinteresting” — the listener writes “forty to nine”.","developing":"The result is framed by pauses in Round 2, but after the one-minute card the speaker races through the close.","competent":"“Waiting times fell // from FOURteen weeks // to NINE.↘” The listener reports both numbers; after the card, the speaker skips a slide but keeps the same pace."}},{"number":3,"title":"Emphasis and intonation","mandatory":false,"question":"Does the voice tell the audience what matters and when a point is complete?","evidence":"Recording: stressed words and final tones","levels":{"beginning":"Little or no stress on key words, or every word stressed; findings end with a rising ‘question’ tone.","developing":"Key words stressed in some sentences but not consistently; some conclusions still rise; or variation exaggerated and artificial.","competent":"Main stress on the key word of each thought group; clear falls on results and conclusions; rises used deliberately; delivery sounds natural."},"examples":{"beginning":"“Sensitivity was ninety-two per cent?↗ Specificity was eighty-eight?↗”","developing":"The main result has a clear fall, but the conclusion slide ends with a rise.","competent":"“What mattered was not the drug — it was the DOSE.↘”"}},{"number":4,"title":"Accuracy and intelligibility of numbers and terminology","mandatory":true,"question":"Are critical numbers and terms accurate, clear and understood?","evidence":"Comprehension check (numbers as heard); recording","levels":{"beginning":"A critical number or term is inaccurate or misheard; key terms stressed so that they are hard to recognise.","developing":"All numbers accurate, but at least one critical number not protected; one key term causes hesitation for the listener.","competent":"Every critical number accurate and reported correctly by the listener after one hearing; numbers protected; key terms readily recognised."},"examples":{"beginning":"“Fifteen” said quickly is written down by the listener as “fifty”.","developing":"Both numbers are heard correctly, but “cardiomyopathy” is stressed on “path” and the listener asks what was meant.","competent":"“Fifteen per cent — roughly one patient in seven.” “Car-di-o-my-OP-a-thy” is recognised immediately."}},{"number":5,"title":"Voice and physical presence","mandatory":false,"question":"Can the audience hear, see and connect with the speaker?","evidence":"Recording, with and without sound","levels":{"beginning":"Sentence endings often inaudible; reading from notes or screen most of the time; distracting movement dominates.","developing":"Generally audible but fades at times; eye contact covers part of the audience; some purposeful gestures alongside persistent habits.","competent":"Audible to the last word; eye contact with the whole audience or the lens; stable stance; gestures support the structure; stillness for the key message."},"examples":{"beginning":"The speaker faces the screen for the key result and sways throughout; the last words of sentences are lost.","developing":"Clear voice and good eye contact, but the clicker is played with during the key result.","competent":"The speaker turns to the slide in silence, turns back, stands still and states the result to the back of the room."}},{"number":6,"title":"Composure, recovery and self-analysis","mandatory":false,"question":"Does the speaker stay in control of the message, and understand their own performance?","evidence":"Recording 3; Final Task analysis","levels":{"beginning":"The disruption derails the talk (long silence, repeated apology, abandoned structure); analysis is general.","developing":"Recovers, but with visible strain or by losing a key point; analysis notes problems but not their causes.","competent":"Acknowledges the disruption briefly, uses a prepared phrase and returns to the key message; analysis uses evidence from the three recordings, explains causes and sets specific priorities."},"examples":{"beginning":"“Oh no, sorry, sorry — I’m so sorry…” followed by ten seconds of silence; the analysis says “I need more confidence”.","developing":"Recovers from the slide failure but forgets to state the key number; the analysis lists ‘too fast’ without saying where or why.","competent":"“We seem to have lost the slides, so let me describe the result instead.” The analysis notes: “In Round 1 the listener heard ‘forty’; pausing and restating fixed it in Rounds 2 and 3; my remaining habit is speeding up at the close because I script it less.”"}}],"debriefQuestions":["Compare your comprehension-check results across the three rounds. What changed, and what caused the change?","Which single technique made the biggest difference for your listener?","Where did your delivery still change under pressure, and why?","Which of your habits did you notice only when watching without sound?","What did your listener find easy to follow, and where did they lose the thread?","Which recovery phrase felt natural, and which will you replace?","What two strengths will you keep, and what two priorities will you work on before Module 12?","What will you do differently in your next real presentation, and how will you know you have done it?"],"transferPlan":[{"heading":"The event","prompt":"Name, date, audience, length and room or format (in person, online, hybrid)."},{"heading":"Two strengths to keep","prompt":"Each linked to a moment in your recordings."},{"heading":"Two priorities","prompt":"Each with the evidence that shows it and its likely cause."},{"heading":"Three commitments","prompt":"Specific and observable, e.g. “Key-result slide: two-second pause before and after; say ‘fifteen per cent, roughly one patient in seven’.”"},{"heading":"Warm-up on the day","prompt":"Your two-minute voice and presence warm-up, and when you will do it."},{"heading":"Recovery plan","prompt":"The disruption you are most likely to meet, your prepared phrase and the three steps."},{"heading":"After the event","prompt":"One line: what happened, and what you will keep or change. Bring it to W6 (group coaching)."}],"practicePassage":{"title":"Academy practice extract (fictional)","text":"Good morning. Thank you, Chair. [pause] In many hospitals, older patients wait too long for pain relief in the emergency department. [pause] Today I want to show you what happened when nurses were allowed to start analgesia from triage — and where it did not help. [pause] I’ll describe the protocol, our results over twelve months, and what we would do differently. … [Key-result slide] Please look at the two bars on the right. [pause] The median time to analgesia fell from seventy-four minutes to thirty-one. [pause] That is forty-three minutes sooner — more than half an hour. … [Close] So, I’ll leave you with one number: // thirty-one minutes. Thank you.","criticalNumbers":["seventy-four minutes","thirty-one minutes","forty-three minutes","twelve months"]},"termCard":[{"term":"cardiomyopathy","stress":"car-di-o-my-OP-a-thy","ipa":"/ˌkɑː.di.əʊ.maɪˈɒp.ə.θi/"},{"term":"epidemiology","stress":"ep-i-de-mi-OL-o-gy","ipa":"/ˌep.ɪ.diː.miˈɒl.ə.dʒi/"},{"term":"anaesthesia","stress":"an-aes-THE-si-a","ipa":"/ˌæn.əsˈθiː.zi.ə/"},{"term":"haemorrhage","stress":"HAEM-or-rhage","ipa":"/ˈhem.ər.ɪdʒ/"},{"term":"analysis","stress":"a-NAL-y-sis","ipa":"/əˈnæl.ə.sɪs/"},{"term":"analyse","stress":"AN-a-lyse","ipa":"/ˈæn.əl.aɪz/"},{"term":"significant","stress":"sig-NIF-i-cant","ipa":"/sɪɡˈnɪf.ɪ.kənt/"},{"term":"hypothesis","stress":"hy-POTH-e-sis","ipa":"/haɪˈpɒθ.ə.sɪs/"},{"term":"cohort","stress":"CO-hort","ipa":"/ˈkəʊ.hɔːt/"},{"term":"oesophagus","stress":"oe-SOPH-a-gus","ipa":"/iˈsɒf.ə.ɡəs/"},{"term":"paediatric","stress":"pae-di-AT-ric","ipa":"/ˌpiː.diˈæt.rɪk/"},{"term":"thirteen / thirty","stress":"thir-TEEN / THIR-ty","ipa":"/θɜːˈtiːn/ · /ˈθɜː.ti/"},{"term":"fifteen / fifty","stress":"fif-TEEN / FIF-ty","ipa":"/ˌfɪfˈtiːn/ · /ˈfɪf.ti/"}],"facilitatorGeneral":["Group size: three participants per group (speaker, timekeeper, listener); rotate roles every round. With an even number, a group of four adds an observer.","Room: space to stand, a screen or a laptop for slides, and the furthest seat available for Station B.","Psychological safety: state at the start that Round 1 is diagnostic, recordings stay with the participant, and accent is never assessed. Pressure cards are optional; a participant can use the written recovery-plan alternative.","Recording ground rules (read aloud at the start): each person records only on their own device; no one records another participant without their agreement; recordings of others are not kept, shared or uploaded; feedback given in the group stays in the group.","Adjustments: ask privately at the start whether anyone needs an adjustment (seated delivery, written comprehension check, captions instead of listening back, written alternative to pressure cards, extra time, or delivery with a communication aid). Use the adjusted route described in the Briefing; agree any replacement criteria with the Academic Director.","Feedback: always one specific strength, one time-referenced observation and one suggestion, using the phrase bank.","Timing: keep to the agenda; if a group runs late, shorten Station A practice rather than the recording rounds.","Pressure cards: draw face down and reveal between 45 and 90 seconds after the speaker starts; standard cards by default; offer a repeat.","Assessment: participants rate themselves; that is self-assessment only. If you are an instructor or assessor confirming the Competent status, observe the participant’s Round 3 live, use the rubric descriptors and examples, record evidence (comprehension check, specific moments), not impressions, and enter the result in the platform’s assessment tool with written feedback."]}}'::jsonb, null, '{"title":"Final Task — performance analysis and transfer plan","brief":"Write an analysis of 250–400 words of your Round 3 performance, using the measurements and comprehension-check results you logged in the three Practice Rounds. Include: (1) the main differences between Rounds 1, 2 and 3, with evidence; (2) two strengths to keep and two priorities to work on; (3) how you handled the pressure card and what you would do next time; and (4) your transfer plan for a named upcoming presentation: three commitments, your warm-up, your recovery phrase and the date. Assess yourself on the six rubric criteria in Practice Round 3 before you submit. If you used the delayed self-check instead of a listener, say so: a self-check is weaker evidence than a listener’s report, so interpret your comprehension results cautiously. Submitting the Final Task completes the workshop (Workshop Completed). The Competent status is separate: it is confirmed only by an instructor who observes your Round 3 performance live, in a facilitated workshop or a coaching session. Keep your Round 3 recording on your own device; you may choose to play it during a live session, but it is never uploaded to the platform.","min_words":250,"required":true,"criteria":[{"criterion":"1 · Opening and audience orientation","description":"Context, purpose and route within about 40 seconds, without apology."},{"criterion":"2 · Pace and pausing for comprehension (mandatory)","description":"A listener reports the key message correctly after one hearing; pauses frame the key result; content, not speed, is reduced under pressure."},{"criterion":"3 · Emphasis and intonation","description":"Main stress on the key word of each thought group; clear falls on results; natural delivery."},{"criterion":"4 · Numbers and terminology (mandatory)","description":"Critical numbers accurate, protected and reported correctly by the listener; key terms readily recognised."},{"criterion":"5 · Voice and physical presence","description":"Audible to the last word; eye contact with the whole audience or lens; stable stance; purposeful gesture; stillness for the key message."},{"criterion":"6 · Composure, recovery and self-analysis","description":"Brief acknowledgement and return to the message; analysis based on evidence from the three rounds, with causes and specific priorities."}]}'::jsonb, null, null, null from public.lessons where code = 'W1'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'W1');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Your extract contains the sentence “Admissions fell by fifteen per cent.” Which delivery best protects the number?', array['Say it quickly so the audience does not lose interest', 'Pause before it, say “fifteen per cent” slowly, and restate it as “about one in seven”', 'Round it to fifty per cent to simplify', 'Leave the number to the slide and do not say it']::text[], 1, 'Fifteen and fifty are easily confused. Showing, slowing and restating critical numbers protects intelligibility (L07).' from public.lessons where code = 'W1';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Which tone should your key result usually end with?', array['A rise, to invite questions', 'A level tone', 'A rise on every word', 'A clear fall, to show the statement is complete']::text[], 3, 'In standard British English a clear fall signals that a statement is complete and that you stand behind it (L08).' from public.lessons where code = 'W1';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You need to point to a detail on your slide while using a fixed lectern microphone. What is the best sequence?', array['Turn and look in silence, turn back to the audience, then speak', 'Explain while looking at the screen', 'Walk to the screen with the microphone', 'Use the laser pointer in quick circles while speaking']::text[], 0, 'Speaking only when facing the audience keeps your voice in range and gives listeners time to look (L08, L09).' from public.lessons where code = 'W1';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'In this workshop, how is speaking rate used?', array['As a pass/fail target of 140 words per minute', 'It is not measured at all', 'As diagnostic information alongside the listener comprehension check', 'As the main criterion for the final assessment']::text[], 2, 'Rate helps diagnose problems such as acceleration under pressure; intelligibility is judged by whether the listener understands.' from public.lessons where code = 'W1';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'Halfway through your extract, the slides fail. What is the strongest response?', array['Apologise and wait in silence until they return', 'Speed up to finish before anyone notices', 'Ask the audience to read the handout', 'Acknowledge it briefly, describe the result in words and continue']::text[], 3, 'A brief acknowledgement and a prepared phrase keep you in control of the message (L02 recovery; W1 phrase bank).' from public.lessons where code = 'W1';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'W1');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'W1 Participant Workbook', 'Extract template, progress sheet, station worksheets, term-stress card, practice extract, debrief and transfer plan with speaker card.', '/materials/workshops/W1-participant-workbook.pdf', false from public.lessons where code = 'W1';
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 2, 'W1 Assessment Rubric', 'Six criteria with Beginning, Developing and Competent descriptors, examples and assessment principles.', '/materials/workshops/W1-assessment-rubric.pdf', false from public.lessons where code = 'W1';
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 3, 'W1 Pressure Cards', 'All ten pressure cards, printable, with recovery strategies.', '/materials/workshops/W1-pressure-cards.pdf', false from public.lessons where code = 'W1';
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 4, 'W1 Facilitator Guide', '120-minute agenda, set-up, timing cues, what to observe, common difficulties, feedback language, debrief questions and observer sheet.', '/materials/workshops/W1-facilitator-guide.pdf', false from public.lessons where code = 'W1';

insert into public.modules (number, slug, title, weeks_label, summary, outcomes) values (4, 'presentation-architecture', 'Presentation Architecture', 'Weeks 3–4', 'Build presentations around one clear message. Structure openings, arguments and conclusions so that complex content becomes memorable.', array['Define a single core message for any presentation', 'Structure talks with proven frameworks for medical audiences', 'Design slides that support speech rather than replace it']::text[])
  on conflict (number) do update set slug = excluded.slug, title = excluded.title, weeks_label = excluded.weeks_label, summary = excluded.summary, outcomes = excluded.outcomes;
insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L10', 'lesson', 'l10-the-core-message', 'The Core Message', 'Reducing a body of work to the one idea your audience must remember.', 60, 4, 1, false, 'not_recorded', 'ready', 'presentation-coach' from public.modules where number = 4
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Most medical presentations fail for a reason that has nothing to do with English. The speaker knows too much, shows too much and never says plainly what the audience should take away. After a busy session, colleagues remember perhaps one idea from each talk — and if the speaker has not chosen that idea, the audience chooses it for them, often from a detail on slide seven. This lesson gives you a disciplined way to decide what your talk is for before you open your slide software. You will learn to reduce a body of work to one core message, to test that message against the audience in front of you, and to build two or three supporting points that carry it. The method is the foundation for the rest of this module: openings and closings in L11 and slide design in L12 both depend on a message you can state in one sentence. It also works in a second language, because a clear message protects you when words are hard to find: you always know where you are going.","objectives":["Write a one-sentence core message for a presentation that states a claim, not a topic","Test a core message against the audience, the setting and the time available, and revise it","Select two or three supporting points and the evidence for each, and cut material that does not serve the message","Deliver a 30-second spoken version of your message without slides"],"sections":[{"heading":"Why experts struggle to simplify","paragraphs":["Doctors who present are usually the people who know the subject best in the room. That is exactly the difficulty. Once you know something well, it becomes hard to imagine not knowing it: abbreviations feel universal, the reasoning feels obvious, and every result feels important because you remember the effort behind it. The audience has none of this context. They meet your work for the first time, at speaking speed, with no way to scroll back.","The practical consequence is that experts overestimate what an audience can absorb and underestimate how much guidance it needs. A clear core message is the simplest correction. It forces you to decide what matters from the audience’s point of view, not from the point of view of the person who did the work."],"callout":{"kind":"evidence","text":"In economic experiments, better-informed participants were unable to ignore their own knowledge when predicting the judgements of less-informed people — an effect the authors called the “curse of knowledge”. The studies did not concern presentations, but they describe the same bias that makes expert talks hard to follow.","refs":[1]}},{"heading":"Topic, title and message are not the same","paragraphs":["A topic is what you talk about: “delirium screening in older surgical patients”. A title is how the programme lists it. A message is what you want the audience to believe or do when you have finished: “Screening every older surgical patient on the first post-operative day detects delirium a day earlier, and it takes two minutes per patient.” Only the message gives the talk a direction.","A useful test is grammatical. A topic is a noun phrase. A message is a complete sentence with a verb, and usually a claim that someone could disagree with. If your sentence cannot be challenged — “Delirium is an important problem” — it is still a topic. If it includes too many clauses to say in one breath, it is still a summary of everything you did, not a message.","Good medical messages are specific about the population, the finding and the consequence. They also respect the strength of the evidence. A single-centre observational study supports “was associated with”, not “prevents”. Precision here is not only a matter of style; it protects your credibility with expert audiences who will notice an overclaim at once."]},{"heading":"Working memory sets the limits","paragraphs":["Listeners hold only a small amount of new information in mind at once. When a talk asks them to track six findings, four abbreviations and a complex graph at the same time, they do not simply remember less of everything; they lose the thread that connects the pieces. Written text can be reread. Speech cannot.","This is why the Academy recommends one core message and no more than three supporting points for a short talk. Each supporting point should be a sentence in its own right, and each should clearly support the message. Additional findings can go into a backup slide, a handout or the answer to a question. Leaving them out of the talk is not hiding them; it is choosing what the audience can actually use."],"callout":{"kind":"evidence","text":"A widely cited review of research on short-term memory concluded that adults can hold roughly three to five meaningful units (“chunks”) in mind at once. Presentations are not memory experiments, but the limit explains why a small number of clearly grouped points is easier to follow than a long list.","refs":[2]}},{"heading":"Building the message: four questions","paragraphs":["Write your message before you open your slides, by answering four questions in order. First: who is in the room, and what do they already know? A message for cardiologists at a specialist congress differs from one for a hospital management board. Second: what do they care about? Patients, workload, cost, safety, training or an open scientific question. Third: what is the single most important thing your work shows them? Fourth: what should they think or do differently afterwards?","Then combine the answers into one sentence and say it aloud. Many speakers find a simple narrative frame helpful: what is known, what is the problem or gap, and therefore what you found or propose. For example: “We know that delirium is common after surgery, but it is often detected late on busy wards; therefore we tested a two-minute screen on day one, and it found delirium a day earlier.” Shortened to its core, this becomes the message.","Finally, check the message against the time available. A five-minute oral presentation can carry one message and one or two points. A forty-minute grand round can carry the same message with three well-developed points and a discussion of limitations. The message stays constant; the depth changes."],"callout":{"kind":"recommendation","text":"The “And, But, Therefore” frame and the problem–gap–finding sequence are widely taught in science communication. They are practical tools, not research findings: use them to draft, then revise the sentence in your own words.","refs":[3,4]}},{"heading":"Supporting points and the evidence for each","paragraphs":["Once the message is fixed, every part of the talk must earn its place by supporting it. List everything you could include — results, methods, background, anecdotes — and sort each item into one of three groups: essential to support the message, useful for questions, and interesting to you but not to this audience. Only the first group goes into the talk.","Arrange the supporting points in the order that makes the message most convincing. For research, this is often problem, method in brief, key result and implication. For a clinical guideline or service change, it may be the current problem, the proposal and what it will mean for the team. Each point should end by connecting back to the message, so the audience hears the same idea from several angles.","Clinicians already use structured formats when communication must be fast and safe. Handover tools such as SBAR — situation, background, assessment, recommendation — exist because a clear structure reduces the effort needed to understand a message under pressure. A presentation is a slower setting, but the principle is the same."],"callout":{"kind":"evidence","text":"SBAR was adopted in clinical settings as a shared structure for communication between clinicians; reports of its implementation describe improved clarity and a common model for escalating concerns. It is cited here as an example of structured clinical communication, not as evidence about presentations.","refs":[5]}},{"heading":"The thirty-second test","paragraphs":["Before you build a single slide, explain your talk aloud in thirty seconds to someone outside your specialty, or record yourself if no one is available. Say the message, name the supporting points and stop. If you cannot do it, the talk is not yet ready, however polished the slides are.","The test has a second benefit for speakers working in a second language. A message you have said aloud many times becomes a phrase you can produce under pressure. When you lose a word in the middle of a talk, you can always return to it: “The point I want you to take away is this: …” Your message becomes both the destination of the talk and a safe place to come back to."]}],"examples":[{"title":"From a topic to a message","setting":"Regional anaesthesia meeting, ten-minute oral presentation","text":"A fictional anaesthetist’s first draft is titled “Experience with ultrasound-guided nerve blocks in our unit” and contains eighteen slides covering technique, equipment, eight outcome measures and a literature review. Asked what the audience should remember, she says: “That we do a lot of blocks.” After the four questions, she writes: “In our unit, adding a block nurse to the team allowed us to provide nerve blocks for hip-fracture patients within four hours of admission, and patients needed less opioid on the first day.” She keeps three outcome measures, moves the rest to backup slides and reduces the talk to nine slides. The talk is shorter, and colleagues ask about staffing — the point she actually wanted to make."},{"title":"One message, two audiences","setting":"Paediatric respiratory service, congress talk and management meeting","text":"A fictional paediatric team has introduced a nurse-led asthma clinic. At a specialist congress, the message is: “A nurse-led review within two weeks of an emergency attendance was associated with fewer repeat attendances over six months in our population.” At the hospital management meeting the next week, the same work becomes: “A nurse-led review after an emergency attendance reduced repeat visits in our pilot; extending it to all sites needs one additional nurse post.” The data are the same. The audience, and therefore the message, are different."},{"title":"Saving a journal club","setting":"Internal medicine journal club, trainee presenting a trial","text":"A fictional trainee prepares twenty-five slides summarising every table of a randomised trial. A consultant suggests a different approach: “Tell us whether this trial should change what we do on Monday.” The trainee rewrites the talk around one sentence: “This trial supports earlier switching from intravenous to oral antibiotics in stable patients, but its population excludes most of our frail elderly patients.” Two supporting points follow — the result and the limitation — and the discussion that follows is the best of the year, because the audience knows what is being argued."}],"phrase_bank":[{"phrase":"The one thing I’d like you to remember is…","use":"Stating your core message explicitly","register":"Neutral","pronunciation":"Stress “ONE”; pause after “is”.","example":"The one thing I’d like you to remember is this: // two minutes of screening finds delirium a day earlier."},{"phrase":"In short, …","use":"Giving the message in its shortest form","register":"Neutral – formal","example":"In short, the block nurse made early analgesia possible."},{"phrase":"This matters because…","use":"Linking a point to the audience’s concerns","register":"Neutral","example":"This matters because late detection means a longer stay."},{"phrase":"I’ll make three points.","use":"Announcing the number of supporting points","register":"Neutral","pronunciation":"Stress “THREE”.","example":"To support that, I’ll make three points: the problem, the change we made, and the result."},{"phrase":"Which brings me back to my main point:","use":"Returning to the message after a supporting point","register":"Neutral","example":"Which brings me back to my main point: early screening is feasible on a busy ward."},{"phrase":"What this means for your practice is…","use":"Turning a finding into a consequence for the audience","register":"Neutral – formal","example":"What this means for your practice is that one question on day one can change management."},{"phrase":"The evidence for this comes from…","use":"Introducing support for a claim","register":"Formal","example":"The evidence for this comes from our audit of four hundred patients."},{"phrase":"We found an association, not proof of cause.","use":"Stating the strength of evidence honestly","register":"Formal","example":"We found an association, not proof of cause, but the size of the difference is worth testing."},{"phrase":"I won’t go into the details of…, but…","use":"Signalling that you are leaving material out","register":"Neutral","example":"I won’t go into the details of the statistics, but they are in the backup slides."},{"phrase":"If you remember nothing else, …","use":"Repeating the message near the end","register":"Neutral, informal","example":"If you remember nothing else, remember the two-minute screen."}],"phrase_practice":"Write your core message as one sentence. Then say it three times aloud, each time introduced by a different expression from the phrase bank, and record the version that sounds most natural to you. Use that version in your opening, after your last supporting point, and in your close.","demonstration":"The instructor video for this lesson has not yet been recorded. It will show a ten-minute talk reduced to its core message in real time: the presenter answers the four questions aloud, writes the message, sorts the slides into three groups and delivers the thirty-second version before and after the revision. Notice how the number of slides falls while the clarity of the spoken message rises.","mistakes":[{"mistake":"Using the title as the message","correction":"Write a complete sentence with a verb and a claim someone could disagree with."},{"mistake":"Including every result because it took work to obtain","correction":"Keep only results that support the message; move the rest to backup slides."},{"mistake":"Overstating the evidence to make the message stronger","correction":"Match the verb to the design: “was associated with”, “suggests”, “showed”."},{"mistake":"Writing the message after the slides","correction":"Write and say the message first; build slides to support it."},{"mistake":"Using the same message for every audience","correction":"Keep the data; adapt the consequence to what this audience cares about."},{"mistake":"Stating the message only once","correction":"State it in the opening, return to it after each point and repeat it in the close."}],"reflection":["Think of the last talk you attended. What was its message — and did the speaker say it?","Which part of your own current work do you find hardest to leave out, and why?","How would the message of your next talk change if the audience were managers rather than specialists?"],"references":["Camerer, C., Loewenstein, G., & Weber, M. (1989). The curse of knowledge in economic settings: An experimental analysis. Journal of Political Economy, 97(5), 1232–1254.","Cowan, N. (2001). The magical number 4 in short-term memory: A reconsideration of mental storage capacity. Behavioral and Brain Sciences, 24(1), 87–114.","Olson, R. (2015). Houston, We Have a Narrative: Why Science Needs Story. University of Chicago Press.","Schimel, J. (2012). Writing Science: How to Write Papers That Get Cited and Proposals That Get Funded. Oxford University Press.","Haig, K. M., Sutton, S., & Whittington, J. (2006). SBAR: A shared mental model for improving communication between clinicians. Joint Commission Journal on Quality and Patient Safety, 32(3), 167–175."]}'::jsonb, '{"title":"From topic to core message","instructions":"Turn the topic of one of your own talks into a core message and a short structure.","steps":["Choose a presentation you will give, or recently gave, and write its title or topic.","Answer the four questions in one or two lines each: audience, what they care about, the most important finding, what they should think or do afterwards.","Combine the answers into one sentence of no more than 35 words, with a verb and a claim. Check that the verb matches the strength of your evidence.","List up to three supporting points, each as a full sentence, and one item you will now leave out.","Say the message and the points aloud in 30 seconds, and note what was hard to say."],"prompt":"Paste your topic, your answers to the four questions, your one-sentence message, your supporting points, what you left out, and a note on the 30-second test.","min_chars":300,"model_answer":"Topic: “Our experience with a frailty screen in the emergency department.”\nAudience: emergency physicians and geriatricians at a regional meeting; they know frailty matters but doubt that screening is feasible in a crowded department. They care about: time, flow and avoidable admissions. Most important finding: triage nurses completed the screen in most eligible patients, and screen-positive patients were referred to geriatrics earlier. Afterwards they should: consider piloting the screen at triage.\nMessage (31 words): “A one-minute frailty screen at triage was completed for most patients over seventy-five in our department, and it brought geriatric review forward without delaying flow — it is feasible elsewhere.”\nSupporting points: (1) Frail older patients waited too long for geriatric review. (2) Triage nurses completed the screen in one minute, with brief training. (3) Geriatric review happened earlier, and time in the department did not increase.\nLeft out: the comparison of three frailty tools — moved to a backup slide.\n30-second test: hard to say “screen-positive” naturally; I will say “patients who screened positive”.","self_check":["The message is a full sentence with a verb and a claim, not a topic.","The verb matches the evidence (association, feasibility or effect).","There are no more than three supporting points, each a full sentence.","At least one item has been deliberately left out.","You said it aloud within about 30 seconds."]}'::jsonb, '{"title":"Message map for your next presentation","brief":"Prepare a one-page message map for a real presentation you will give in the next three months. Include: (1) the setting, audience and time available; (2) your core message in one sentence; (3) two or three supporting points, each with the evidence that supports it; (4) a list of material you have decided to leave out or keep for questions, with a one-line reason; and (5) a short reflection (150–250 words) on how the message changed during drafting and how you would adapt it for a different audience. This map will be the starting point for Workshop II (Structure Clinic).","min_words":200,"required":true,"criteria":[{"criterion":"Message","description":"One complete sentence that makes a specific, defensible claim for this audience."},{"criterion":"Evidence and precision","description":"The wording matches the strength of the evidence; no overclaiming."},{"criterion":"Structure","description":"Two or three supporting points, each clearly linked to the message and to evidence."},{"criterion":"Selection","description":"Material left out is identified, with reasons."},{"criterion":"Reflection","description":"Shows how the message was tested and how it would change for another audience."}]}'::jsonb, null, null, null from public.lessons where code = 'L10'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L10');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Which of these is a core message rather than a topic?', array['Antibiotic stewardship in surgical wards', 'Our experience with antibiotic stewardship', 'Stopping prophylactic antibiotics after 24 hours halved their use on our surgical wards, with no rise in wound infections', 'Important lessons from stewardship']::text[], 2, 'A message is a complete sentence that makes a specific claim. The other options are topics or titles.' from public.lessons where code = 'L10';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Your single-centre observational study found that patients seen by the new clinic had fewer readmissions. Which message wording is most appropriate for a specialist audience?', array['The new clinic prevents readmissions', 'Attendance at the new clinic was associated with fewer readmissions in our population', 'Readmissions are a serious problem', 'The clinic proves that follow-up works']::text[], 1, 'An observational design supports “was associated with”. Overclaiming damages credibility with expert listeners.' from public.lessons where code = 'L10';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You have a five-minute oral slot and seven interesting findings. What should you do?', array['Present all seven quickly', 'Choose the findings that support one message, present two or three, and keep the rest for questions', 'Present the methods in detail and leave the findings for the poster', 'Ask the chair for more time']::text[], 1, 'Listeners can hold only a few new units in mind. A small number of points that support one message is easier to follow and remember.' from public.lessons where code = 'L10';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'What is the main reason experts find it hard to simplify their own work?', array['Their English is not good enough', 'Medical content cannot be simplified', 'Audiences prefer complex talks', 'Once you know something well, it is hard to imagine not knowing it']::text[], 3, 'The “curse of knowledge” makes it difficult to judge what a less-informed audience needs.' from public.lessons where code = 'L10';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'You present the same audit to a specialist congress and to the hospital board. What should change?', array['The consequence you emphasise, to match what each audience cares about', 'The data, so that the board sees better results', 'Nothing; the message should be identical', 'Only the slide colours']::text[], 0, 'The evidence stays the same; the message is adapted to the audience’s concerns, such as practice for specialists and resources for managers.' from public.lessons where code = 'L10';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'Halfway through your talk you lose the next word and your mind goes blank. Which strategy from this lesson helps most?', array['Apologise for your English', 'Skip to the last slide', 'Return to your rehearsed message: “The point I want you to take away is this: …”', 'Read the slide word for word']::text[], 2, 'A message you have said aloud many times is a safe phrase to return to, and it re-orients both you and the audience.' from public.lessons where code = 'L10';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L10');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L10 Lesson handout', 'The four questions, message test, message map template, evidence verbs and phrase bank.', '/materials/lessons/L10-handout.pdf', false from public.lessons where code = 'L10';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L11', 'lesson', 'l11-openings-and-closings-that-work', 'Openings and Closings That Work', 'Starting with relevance and ending with a clear take-home message and call to action.', 60, 4, 2, false, 'not_recorded', 'ready', 'presentation-coach' from public.modules where number = 4
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"The first and last minutes of a presentation do more work than any other part. In the opening, the audience decides whether your talk is relevant to them and whether they can follow you. In the close, they decide what to take away. Many medical talks waste both: they open with thanks, an outline slide and a long background, and they end with “That’s all — any questions?”. In L01 you practised opening without apology, and in L02 you rehearsed your first thirty seconds to manage nerves. This lesson is about content: what an opening and a closing must achieve, which devices work for medical audiences, and how to write both so that they carry the core message you defined in L10. You will finish with a scripted opening and closing for a real talk, and a habit you can use for every presentation, from a five-minute oral to a keynote.","objectives":["Write an opening that establishes relevance, a gap or question, your core message and the route of the talk within about one minute","Choose an opening device suited to the audience and setting, and avoid devices that waste the first minute","Write a closing that restates the message, gives a specific take-home and call to action, and ends on a planned final sentence","Signpost the structure of a talk so that listeners always know where they are"],"sections":[{"heading":"Why beginnings and endings carry so much weight","paragraphs":["Audiences pay most attention at the start, when they are deciding whether to listen, and again at the end, when they sense that the important conclusion is coming. In between, attention drifts, especially in long sessions and in a second language. The practical lesson is simple: put your message where attention is highest, and do not spend those moments on administration.","Endings also shape how the whole experience is remembered. A talk that closes clearly, on its main point, leaves a different impression from one that runs out of time and stops in the middle of a slide. You cannot control everything an audience remembers, but you can make sure that the last thing they hear is the thing you most want them to keep."],"callout":{"kind":"evidence","text":"In classic memory research, items at the beginning and end of a list were recalled better than those in the middle (primacy and recency effects). In a study of patients undergoing colonoscopy, retrospective ratings of discomfort were strongly influenced by the worst moment and by the final minutes of the procedure. Neither study concerned presentations; they are cited because they illustrate why the start and the end deserve special care.","refs":[1,2]}},{"heading":"The four jobs of an opening","paragraphs":["An effective opening does four jobs, usually in this order. It establishes relevance: why this topic matters to these people, today. It opens a gap: the question, problem or uncertainty that your work addresses. It states the message, or at least promises it clearly. And it gives a route: two or three signposts that show how the talk will proceed.","In practice this can take less than a minute. “Every one of us has seen an older patient become confused after surgery. On a busy ward, we often notice it a day or two late. Today I want to show you that a two-minute screen on the first post-operative day finds delirium a day earlier. I’ll show you why we tried it, how it works on the ward, and what happened.” Relevance, gap, message, route — and the audience knows exactly why to listen.","Thanks to the chair and organisers belong in a single short sentence, or in your first answer to a question. Your name and affiliation are usually announced by the chair and printed on the programme. An outline slide that lists “Introduction, Methods, Results, Discussion” adds nothing; a spoken route that names your actual points adds a great deal."]},{"heading":"Opening devices for medical audiences","paragraphs":["Four devices work reliably with medical audiences. A short, anonymised clinical vignette makes the problem concrete: “A seventy-eight-year-old man is admitted with a hip fracture on a Friday night…” It must be fictional or composite, and never identifiable. A striking, verified number gives scale: “One in five patients over seventy will develop delirium after surgery” — but only if the source supports it and you can cite it. A genuine question engages the audience’s curiosity, provided you answer it. A contrast between what people assume and what is true can be powerful, if it does not caricature colleagues.","Some devices rarely work, especially across cultures and languages. Jokes depend on shared references and timing, and they are the first thing to fail in a second language. Famous quotations are often misattributed and feel generic. Rhetorical questions that you do not answer frustrate an expert audience. Dictionary definitions waste time on what everyone knows. And opening with the limitations of your study undermines your message before you have stated it."],"callout":{"kind":"evidence","text":"Research on curiosity suggests that it arises when people become aware of a gap in their knowledge that they want to close. A well-chosen question or unexpected finding in the opening creates such a gap — provided the talk then closes it.","refs":[3]}},{"heading":"Signposting: keeping the audience with you","paragraphs":["Readers can see headings, page numbers and how much text remains. Listeners cannot. Signposts are the spoken equivalent: short phrases that tell the audience where they are, what has just finished and what comes next. “So that was the problem. Now let me show you what we changed.” They feel repetitive to the speaker; to the audience they are a map.","Use the route from your opening as your structure, and refer back to it. If you promised three points, say “The second point is…” and “Finally, the third point…”. At each transition, link the point you have just made to your message. In a second language, signposts have a further advantage: they are fixed phrases that you can prepare in advance, so they give you a moment of fluency and a breath at exactly the points where you change direction."],"callout":{"kind":"recommendation","text":"Plan a signpost for every transition between your supporting points and write it on your speaker notes. This is Academy guidance drawn from professional practice in presentation teaching."}},{"heading":"Closings that are remembered","paragraphs":["A strong closing has three parts. First, a signal that you are concluding: “To conclude…” or “Let me finish with…”. Audiences re-engage at this signal, so make sure what follows is worth it. Second, the message, restated in the same words you used in the opening, with the evidence from your supporting points briefly recalled. Third, a take-home and, where appropriate, a call to action: what the audience should think, check or do differently.","A call to action works best when it is specific and realistic. “We should all improve delirium care” changes nothing. “If your ward does not screen on day one, try the two-minute test for one month and audit what you find” gives listeners something they can actually do. Specific plans that say when, where and how are more likely to be acted on than general intentions.","Plan your final sentence word for word and end on it. Then thank the audience, and stop. Avoid ending with “That’s all”, with an apology for running over, or with a slide titled “Questions?” that replaces your message. If there is time for questions, many experienced speakers add a brief return to the message after the last answer: “Thank you for the questions. The point I’d like you to take away is still…”"],"callout":{"kind":"evidence","text":"Research on implementation intentions has found that people are more likely to act on a goal when they specify when, where and how they will act. The studies concern individual goals rather than audiences, but they support making a call to action concrete.","refs":[4]}},{"heading":"Scripting and rehearsing the edges","paragraphs":["Most experienced presenters do not script whole talks, but many script the first and last minute word for word. These are the moments when nerves are highest and when the exact words matter most. Write both, read them aloud, and cut every sentence that does not do one of the jobs described above.","Then rehearse them until you can deliver them while looking at the audience rather than at your notes, combining the content from this lesson with the delivery skills from L02, L07 and L08: a pause before the message, a clear falling tone at the end of it, and eye contact on the final sentence. Your opening and closing will become the most reliable parts of every talk you give."]}],"examples":[{"title":"The same opening, rewritten","setting":"Cardiology congress, eight-minute oral presentation","text":"First draft (fictional): “Good morning. First of all I would like to thank the organisers for inviting me. My name is Dr K. and I work in the department of cardiology. Today I will talk about heart failure. Here is the outline: introduction, methods, results and conclusions. Heart failure is defined as…” — fifty seconds, and no reason to listen. Rewritten: “Thank you, Chair. Almost half of our patients with heart failure are readmitted within a year, and many of those admissions begin with a weight gain that nobody saw. We asked whether a daily weight message to a nurse could change that. In our pilot, it was associated with fewer readmissions — and I’ll show you the result, the cost, and what we would do differently.” Forty seconds, with relevance, gap, message and route."},{"title":"A vignette that respects confidentiality","setting":"Paediatric grand round, quality-improvement project","text":"A fictional paediatrician opens with: “Imagine a four-year-old with a fever, arriving at 3 a.m. on a night when the department is full. Her parents have waited two hours. She has sepsis, and the first antibiotic dose comes three hours after arrival.” She then adds: “This is a composite of several cases, but every element happened in our department last winter.” The vignette makes the problem real for every clinician in the room, and the explicit statement protects confidentiality and honesty."},{"title":"A closing that changed practice","setting":"Surgical audit meeting, ten-minute presentation","text":"A fictional surgical trainee ends a talk on post-operative fluid prescribing: “To conclude: on our wards, one in three fluid prescriptions after day two was unnecessary, and stopping them did not cause harm. So here is my request: from next Monday, please review every fluid chart at the morning ward round, using the one-line checklist on your handout. We will re-audit in March. Thank you.” The final sentence is a date, the call to action is specific, and the audit lead asks for the checklist after the session."}],"phrase_bank":[{"phrase":"Thank you, Chair.","use":"Brief acknowledgement before your opening","register":"Formal","pronunciation":"One short phrase; then pause.","example":"Thank you, Chair. // Almost half of our patients…"},{"phrase":"Every one of us has seen…","use":"Establishing relevance through shared experience","register":"Neutral","example":"Every one of us has seen a patient become confused after surgery."},{"phrase":"What we don’t yet know is…","use":"Opening the gap or question","register":"Neutral – formal","example":"What we don’t yet know is whether screening changes outcomes."},{"phrase":"Today I want to show you that…","use":"Stating your message in the opening","register":"Neutral","pronunciation":"Stress the key word of the message that follows.","example":"Today I want to show you that a two-minute screen finds delirium a day earlier."},{"phrase":"I’ll do this in three steps.","use":"Giving the route","register":"Neutral","example":"I’ll do this in three steps: the problem, our approach and the results."},{"phrase":"So that was…; now let’s look at…","use":"Signposting a transition","register":"Neutral","example":"So that was the problem; now let’s look at what we changed."},{"phrase":"This is a composite case.","use":"Stating that a vignette is not a real, identifiable patient","register":"Neutral – formal","example":"This is a composite case, but every element is familiar."},{"phrase":"To conclude, …","use":"Signalling the closing","register":"Neutral – formal","pronunciation":"Pause after “conclude”.","example":"To conclude, // early screening is feasible and finds delirium sooner."},{"phrase":"So here is my request:","use":"Introducing a specific call to action","register":"Neutral","example":"So here is my request: try the screen for one month on your ward."},{"phrase":"The point I’d like you to take away is…","use":"Restating the message after questions","register":"Neutral","example":"Thank you for the questions. The point I’d like you to take away is still this: screen on day one."}],"phrase_practice":"Write your opening using four expressions from the phrase bank — one for each job — and your closing using “To conclude” and “So here is my request”. Read both aloud, then replace any phrase that does not sound like you with your own words, keeping the function.","demonstration":"The instructor video for this lesson has not yet been recorded. It will show the same talk opened in two ways — the conventional opening with thanks, outline and definitions, and a rewritten opening with relevance, gap, message and route — and closed in two ways, ending with “Any questions?” and ending with a planned final sentence. Notice where the audience’s attention is directed in each version and how long each opening takes before the message appears.","mistakes":[{"mistake":"Spending the first minute on thanks, name and outline","correction":"One sentence of thanks; then relevance, gap, message and route."},{"mistake":"Starting with a joke or a famous quotation","correction":"Use a vignette, a verified number, a genuine question or a contrast."},{"mistake":"Asking a question and never answering it","correction":"Answer every question you raise in the opening, ideally in the close."},{"mistake":"Using a real, recognisable patient story","correction":"Use a fictional or composite case and say so."},{"mistake":"Ending with “That’s all — any questions?”","correction":"End with your message and a planned final sentence; then thank the audience."},{"mistake":"A vague call to action","correction":"Say who should do what, where and by when."}],"reflection":["How did the last three talks you attended begin and end? Which would you copy?","What is the first sentence of your next talk going to be — and which job does it do?","What do you want your audience to do on the Monday after your talk?"],"references":["Murdock, B. B. (1962). The serial position effect of free recall. Journal of Experimental Psychology, 64(5), 482–488.","Redelmeier, D. A., & Kahneman, D. (1996). Patients’ memories of painful medical treatments: Real-time and retrospective evaluations of two minimally invasive procedures. Pain, 66(1), 3–8.","Loewenstein, G. (1994). The psychology of curiosity: A review and reinterpretation. Psychological Bulletin, 116(1), 75–98.","Gollwitzer, P. M. (1999). Implementation intentions: Strong effects of simple plans. American Psychologist, 54(7), 493–503."]}'::jsonb, '{"title":"Rewrite an opening and a closing","instructions":"Rewrite the first and last minute of one of your own talks so that each does its jobs.","steps":["Write down, as accurately as you can, how one of your recent talks began and ended.","Rewrite the opening so that it establishes relevance, opens a gap, states your core message (from L10) and gives a route — in no more than about 120 words.","Choose one opening device (vignette, number, question or contrast) and check it: is it fictional or verified, and is it answered later?","Rewrite the closing with a concluding signal, the message in the same words as the opening, a specific call to action and a final sentence — in no more than about 100 words.","Read both aloud and time them; mark the pause before your message."],"prompt":"Paste your original opening and closing, your rewritten versions, the device you chose and your timings.","min_chars":400,"model_answer":"Original opening (fictional): “Good afternoon, thank you for having me. I am a nephrologist. My talk is about hyperkalaemia. First a definition…”\nRewritten opening (92 words): “Thank you, Chair. Most of us have been called at night about a potassium of six point five — and most of us have wondered whether the result was real. In our hospital, one in four of those night-time results came from a haemolysed sample. Today I want to show you that a simple change to how we take samples can halve unnecessary night-time calls. I’ll show you the problem, the change we made in the emergency department, and what happened to the calls.” Device: a shared experience plus a verified local number from our audit.\nOriginal closing: “So that’s it. Any questions?”\nRewritten closing (74 words): “To conclude: one in four night-time hyperkalaemia calls came from haemolysed samples, and a change in sampling technique halved them. So here is my request: if you work in the emergency department, use the new sampling checklist from next week, and we will share the call data with you in three months. Fewer false alarms means more time for the patients who really need us at night. Thank you.”\nTimings: opening 38 seconds; closing 31 seconds.","self_check":["The opening does all four jobs: relevance, gap, message and route.","The device is fictional or verified, and any question is answered.","There is at most one short sentence of thanks before the content.","The closing restates the message in the same words as the opening.","The call to action says who, what and when, and the final sentence is planned."]}'::jsonb, '{"title":"Scripted opening and closing","brief":"Write the complete opening and closing of a real presentation you will give, based on the message map from L10. The opening (about 100–150 words) must establish relevance, open a gap, state your message and give a route; the closing (about 80–120 words) must signal the conclusion, restate the message, include a specific take-home or call to action and end on a planned final sentence. Mark the pauses and the stressed word of your message (L07). Add a short commentary (100–200 words) explaining your choice of opening device, how you made it accurate and non-identifiable, and how you would shorten both for a five-minute slot.","min_words":250,"required":true,"criteria":[{"criterion":"Opening","description":"Relevance, gap, message and route are all present, in about one minute."},{"criterion":"Device","description":"The opening device suits the audience, is fictional or verified, and is resolved later in the talk."},{"criterion":"Closing","description":"Concluding signal, restated message, specific call to action and a planned final sentence."},{"criterion":"Consistency","description":"The message is stated in the same words in the opening and the closing."},{"criterion":"Delivery marking","description":"Pauses and stress are marked as in L07."}]}'::jsonb, null, null, null from public.lessons where code = 'L11'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L11');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Which four jobs should an opening do?', array['Establish relevance, open a gap or question, state the message and give a route', 'Thank the organisers, introduce yourself, define terms and show the outline', 'Tell a joke, present the methods, show the results and take questions', 'State the limitations, apologise for your English, show the outline and begin']::text[], 0, 'Relevance, gap, message and route tell the audience why to listen, what you will argue and how the talk is organised.' from public.lessons where code = 'L11';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'You want to open with a patient story. What is the right approach?', array['Use last week’s patient with the date changed', 'Avoid stories completely in medical talks', 'Use a fictional or composite case and say that it is composite', 'Show the patient’s imaging with the name blurred']::text[], 2, 'Vignettes are powerful, but they must never be identifiable. Saying that a case is composite protects both confidentiality and honesty.' from public.lessons where code = 'L11';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You have six minutes. Your current opening thanks five people, shows an outline slide and defines the disease. What is the best change?', array['Speak faster so that the opening fits', 'Replace it with one sentence of thanks, then relevance, gap, message and route', 'Keep it, because politeness is essential', 'Move the definition to the end']::text[], 1, 'The opening is when attention is highest; it should carry your message, not administration.' from public.lessons where code = 'L11';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'Why are signposts especially important in spoken presentations?', array['They make the talk longer', 'They replace the need for slides', 'They are required by congress organisers', 'Listeners cannot see headings or how much remains, so they need a spoken map']::text[], 3, 'Signposts are the spoken equivalent of headings; they help listeners follow the structure.' from public.lessons where code = 'L11';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'Which call to action is most likely to lead to change?', array['“We should all think more about fluids.”', '“Fluids are important.”', '“Please review every fluid chart at the morning ward round from next Monday, using the checklist on your handout.”', '“Any questions?”']::text[], 2, 'Specific plans that say who, what and when are more likely to be acted on than general intentions.' from public.lessons where code = 'L11';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'The question-and-answer session ends with a difficult technical question. What is a strong way to finish?', array['Briefly return to your message: “The point I’d like you to take away is still…”', 'Say “That’s all” and leave the stage', 'Apologise for not knowing everything', 'Start a new topic']::text[], 0, 'A short return to the message ensures that it, not the last question, is what the audience remembers.' from public.lessons where code = 'L11';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L11');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L11 Lesson handout', 'The four jobs of an opening, opening devices, signpost phrases, closing structure and call-to-action checklist.', '/materials/lessons/L11-handout.pdf', false from public.lessons where code = 'L11';

insert into public.lessons (module_id, code, kind, slug, title, summary, duration_minutes, week, position, is_preview, video_status, content_status, ai_teacher)
  select id, 'L12', 'lesson', 'l12-slides-as-visual-support', 'Slides as Visual Support', 'Evidence-informed slide design: one idea per slide, readable data, and speaking without reading.', 55, 4, 3, false, 'not_recorded', 'ready', 'presentation-coach' from public.modules where number = 4
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"In medicine, slides often become the presentation. They are written as documents, read aloud by the speaker and photographed by an audience that has stopped listening. For a speaker working in a second language the temptation is even stronger: a full slide feels like a safety net. This lesson argues the opposite. Slides work best when they support what you say — showing the evidence for a claim that you make aloud — and when they are designed for people who see each one for a few seconds from the back of a room. You will learn the assertion–evidence approach, how to present data that can be read at a glance, how to make slides accessible to every member of an international audience, and how to speak from your slides without reading them. The lesson builds directly on your core message (L10) and your signposts (L11): every slide should make one point that supports them.","objectives":["Rewrite a text-heavy slide as an assertion–evidence slide with a sentence headline and visual evidence","Choose and simplify a chart or table so that its main comparison can be read in a few seconds","Check a slide for readability and accessibility: text size, contrast, colour use, abbreviations and confidentiality","Present a slide by speaking from it rather than reading it, using the sequence look, pause, conclude"],"sections":[{"heading":"What slides are for","paragraphs":["An audience can either read or listen; it does not do both well at the same time. When a slide is full of sentences, listeners start reading, usually faster or slower than you speak, and they stop hearing you. If you then read the same text aloud, the slide and the speech compete for the same attention. The result is a talk that is harder to follow than either the slide or the speech alone.","Slides are most useful for what speech cannot do well: showing images, data, anatomy, processes and relationships. Text on slides should be limited to what helps the audience to see the point — a headline, labels and a few words of emphasis. Detailed methods, references and the full results belong in a handout, a backup slide or the published paper."],"callout":{"kind":"evidence","text":"In studies of multimedia learning, people learned less when identical on-screen text was presented at the same time as narration than when they heard the narration alone — the “redundancy effect”. A psychological analysis of slide presentations also found frequent violations of principles of perception, memory and comprehension. These studies were not of medical congress talks, but they consistently point in the same direction.","refs":[1,2,3]}},{"heading":"One slide, one point: the assertion–evidence approach","paragraphs":["The assertion–evidence approach replaces the familiar topic heading and bullet list with two elements. The headline is a complete sentence — an assertion — that states the point of the slide: “Readmissions fell by a third after the nurse-led review”, not “Results”. The body is visual evidence for that assertion: a graph, an image, a diagram or a small table, with minimal text.","This format has three advantages. The audience knows the point even if they look away for a moment. You know what to say, because the headline is your spoken sentence. And the sequence of headlines, read on their own, becomes the argument of the talk — a useful check that every slide supports the core message from L10. If two consecutive headlines say the same thing, merge the slides; if a headline does not connect to your message, the slide probably belongs in the backup section."],"callout":{"kind":"evidence","text":"In studies with engineering students, sentence headlines produced better recall of the main points than phrase headlines, and slides designed with an assertion and visual evidence produced better comprehension than topic-and-bullet slides. The studies were conducted in educational settings, not at medical congresses, so treat the size of the effect with caution.","refs":[4,5]}},{"heading":"Data that can be read in seconds","paragraphs":["Most medical slides contain data, and most data slides contain too much. Begin by deciding which single comparison supports the headline. Then choose a format that makes that comparison easy to see. People judge positions along a common scale, such as the heights of bars from the same baseline or points on the same axis, more accurately than angles, areas or colour intensity. This is why a simple bar or dot chart is usually clearer than a pie chart or a three-dimensional graph.","Simplify ruthlessly. Remove gridlines, unnecessary decimal places, legends that can be replaced by direct labels, and every series that does not serve the point. Highlight the comparison that matters — for example, the intervention group in a strong colour and the control in grey — and label it directly. If you must show a table, reduce it to the rows and columns the audience needs, and highlight the key cell.","When you present the slide, apply the sequence from L07: tell the audience where to look, pause while they look, and then state the conclusion in the words of your headline. A data slide without this guidance asks every member of the audience to interpret the graph alone, in a few seconds, and they will not all reach the same conclusion."],"callout":{"kind":"evidence","text":"Experiments on graphical perception found that judgements of position along a common scale were more accurate than judgements of length, angle or area. This supports bar and dot charts over pie charts when exact comparisons matter.","refs":[6]}},{"heading":"Readable and accessible slides","paragraphs":["Design for the person in the back row, on a small screen in a hybrid session, and with less-than-perfect vision. As professional guidance, use body text of at least 24 points and headlines of at least 32 points on a standard widescreen slide, a plain sans-serif font, and strong contrast between text and background. Test each slide by viewing it at the size of a laptop screen from two metres away, or by shrinking it to a quarter of the screen: if you cannot read it, neither can your audience.","Do not rely on colour alone to carry meaning. Red–green colour vision deficiency is common, especially among men, so a graph in which the only difference between groups is red versus green may be unreadable for several people in a large audience. Use colour together with labels, line styles or position, and choose colour pairs such as blue and orange that remain distinguishable.","For international audiences, write abbreviations in full at first use, avoid local acronyms and idioms, and keep the language of slides simple. Never show identifiable patient information, including faces, names, dates of birth or rare combinations of details, without explicit consent and approval under your institution’s policies. Use images and figures only when you have the right to do so, and acknowledge their sources."],"callout":{"kind":"evidence","text":"A review of worldwide data reported that red–green colour vision deficiency affects about 8% of men and about 0.4% of women of northern European origin, with lower but still important prevalence in other populations.","refs":[7]}},{"heading":"Speaking from slides, not reading them","paragraphs":["If your slides contain only headlines and evidence, you cannot read them aloud — which is the point. You need a different safety net: speaker notes with a few keywords for each slide, the headline sentence you will say, the number you must protect, and the signpost that leads to the next slide. Practise each slide by looking at it for two seconds, turning to the audience and saying the point in your own words.","Plan the moment each slide appears. Let the audience look at a new slide for a second or two before you speak, or tell them what to look at first. Use the blank or black slide function when you want attention back on you, for example during a story or a key message. And prepare backup slides after your closing slide for details you expect to be asked about; showing one in answer to a question is far more effective than squeezing it into the talk.","Finally, check the practical details early: the congress template and aspect ratio, embedded fonts, videos that play without an internet connection, and a copy of the file on a memory stick and in your email. Many apparent slide problems on the day are file problems that could have been prevented."],"callout":{"kind":"recommendation","text":"Before every talk, read only your slide headlines in order. If they tell the story of your talk and support your core message, the structure is sound. This is an Academy practice recommendation."}}],"examples":[{"title":"From bullet list to assertion and evidence","setting":"Infectious diseases congress, results slide","text":"A fictional microbiologist’s original slide is titled “Results” and lists seven bullet points: sample size, median age, three resistance rates, a p-value and a comment. She reads all seven aloud. Rewritten, the headline says: “Resistance to the first-line antibiotic doubled in five years.” The body shows one bar chart with five bars, one per year, the last bar in a strong colour and directly labelled with the percentage. The other figures move to a backup slide. She says: “Look at the last bar.” She pauses. “Resistance has doubled in five years — which is why we changed our guideline.” Colleagues remember the result, and the guideline."},{"title":"A Kaplan–Meier curve for the back row","setting":"Oncology grand round, hybrid session","text":"A fictional oncologist’s survival curve comes directly from the published paper: small axis labels, four lines in similar colours, a dense risk table and a legend in the corner. Online participants report that they cannot read it. For the next session she redraws it with two lines only — the comparison her headline refers to — in dark blue and orange with different line styles, labels each line at its end, enlarges the axes and moves the risk table to a backup slide. She keeps the original figure available as a handout with the full citation."},{"title":"Speaking without the script on screen","setting":"Teaching session for nursing and medical students","text":"A fictional nephrologist who presents in his second language has always used full sentences on slides as a prompt. He moves the sentences to his speaker notes, keeps only headlines and diagrams on the slides, and practises each slide three times while looking at the room. In the session he glances at the headline, turns to the students and explains. At one point he loses a word; he looks at the headline, says it aloud and continues. Feedback afterwards mentions that he seemed “much more in contact with the group”."}],"phrase_bank":[{"phrase":"This slide shows that…","use":"Stating the assertion of a slide","register":"Neutral","example":"This slide shows that resistance has doubled in five years."},{"phrase":"Please look at…","use":"Directing attention before you speak","register":"Neutral","pronunciation":"Pause after the object, before the conclusion.","example":"Please look at the orange line. //"},{"phrase":"On the left you can see…, and on the right…","use":"Explaining a two-part visual","register":"Neutral","example":"On the left you can see the old pathway, and on the right the new one."},{"phrase":"The key comparison here is…","use":"Highlighting the comparison that matters","register":"Neutral – formal","example":"The key comparison here is between the first and the last year."},{"phrase":"I’ve highlighted…","use":"Explaining the use of colour or emphasis","register":"Neutral","example":"I’ve highlighted the intervention group in blue."},{"phrase":"I won’t go through every number; the important one is…","use":"Selecting from a table","register":"Neutral","example":"I won’t go through every number; the important one is the readmission rate at six months."},{"phrase":"The full details are in the handout.","use":"Moving detail out of the talk","register":"Neutral","example":"The full details are in the handout, with all the references."},{"phrase":"I’ll come back to this slide if there are questions.","use":"Postponing detail to a backup slide","register":"Neutral","example":"I’ll come back to this slide if there are questions about the subgroups."},{"phrase":"Let me take the slide away for a moment.","use":"Returning attention to the speaker","register":"Neutral","example":"Let me take the slide away for a moment, because this is the main point."},{"phrase":"This image is shown with the patient’s consent.","use":"Stating consent for a clinical image","register":"Formal","example":"This image is shown with the patient’s written consent and has been anonymised."}],"phrase_practice":"Take your three most important slides. For each, say its headline as a sentence beginning “This slide shows that…”, then present it with “Please look at…”, a pause and your conclusion. Record yourself and check that you spoke to the audience, not to the screen.","demonstration":"The instructor video for this lesson has not yet been recorded. It will show one results slide presented three times: read aloud from a bullet list, presented from an assertion–evidence version without guidance, and presented with “look, pause, conclude”. It will then show the same chart before and after simplification, viewed from the back of a lecture theatre and on a laptop in a hybrid session. Notice where the audience looks in each version and how long it takes to see the main comparison.","mistakes":[{"mistake":"Writing the talk on the slides and reading it","correction":"Put sentences in speaker notes; show a headline and visual evidence."},{"mistake":"Topic headings such as “Results” or “Background”","correction":"Use a sentence headline that states the point of the slide."},{"mistake":"Pasting complex figures directly from papers","correction":"Redraw to show the one comparison that supports your headline; offer the original in a handout."},{"mistake":"Using red and green as the only difference between groups","correction":"Use colour-blind-safe pairs and add labels or line styles."},{"mistake":"Small text that cannot be read from the back of the room","correction":"Body text of at least 24 points, headlines of at least 32; test at reduced size."},{"mistake":"Showing identifiable patient images without consent","correction":"Use anonymised or consented images only, and say so."}],"reflection":["Which of your current slides could you not present if the projector failed — and what does that tell you about it?","Read only the headlines of your last presentation. Do they tell its story?","Who in your usual audience might struggle to read your slides, and what would help them?"],"references":["Kalyuga, S., Chandler, P., & Sweller, J. (2004). When redundant on-screen text in multimedia technical instruction can interfere with learning. Human Factors, 46(3), 567–581.","Mayer, R. E. (2020). Multimedia Learning (3rd ed.). Cambridge University Press.","Kosslyn, S. M., Kievit, R. A., Russell, A. G., & Shephard, J. M. (2012). PowerPoint® presentation flaws and failures: A psychological analysis. Frontiers in Psychology, 3, 230.","Alley, M., Schreiber, M., Ramsdell, K., & Muffo, J. (2006). How the design of headlines in presentation slides affects audience retention. Technical Communication, 53(2), 225–234.","Garner, J., & Alley, M. (2013). How the design of presentation slides affects audience comprehension: A case for the assertion–evidence approach. International Journal of Engineering Education, 29(6), 1564–1579.","Cleveland, W. S., & McGill, R. (1984). Graphical perception: Theory, experimentation, and application to the development of graphical methods. Journal of the American Statistical Association, 79(387), 531–554.","Birch, J. (2012). Worldwide prevalence of red–green color deficiency. Journal of the Optical Society of America A, 29(3), 313–320."]}'::jsonb, '{"title":"Rebuild one slide","instructions":"Turn one real, text-heavy slide from your own work into an assertion–evidence slide and plan how you will present it.","steps":["Choose a slide from one of your talks that contains a lot of text or a complex chart. Describe it briefly (title, number of lines or series, what you used to say).","Write a sentence headline that states its single point and supports your core message from L10.","Describe the visual evidence you will use instead of text: chart type, what you will remove, what you will highlight and how you will label it.","Check it against the readability list: text size, contrast, colour not used alone, abbreviations written in full, no identifiable patient information, permission for any image.","Write what you will say, using the sequence look, pause, conclude, and note what moves to speaker notes or a backup slide."],"prompt":"Paste your description of the original slide, the new headline, the description of the visual evidence, your checklist results and your spoken script for the slide.","min_chars":350,"model_answer":"Original slide (fictional): “Results” — nine bullet points: number of patients, mean age, sex ratio, HbA1c at baseline and 12 months in two groups, two p-values, hypoglycaemia events and a comment. I used to read every line.\nHeadline: “Patients in the telephone coaching group lowered their HbA1c twice as much in a year, without more hypoglycaemia.”\nVisual evidence: a dot chart with two groups at baseline and 12 months, connected by lines; coaching group in dark blue, usual care in grey, both labelled at the end of the line with the change. Removed: sex ratio, mean age and p-values (to backup slide); gridlines; legend. A small line under the chart: “Severe hypoglycaemia: 2 vs 3 events”.\nChecklist: text 28 points, headline 36; dark text on white; groups differ by colour, label and position; “HbA1c” written in full at first use in the talk (“glycated haemoglobin, HbA1c”); no patient data; chart redrawn from our own data.\nScript: “Please look at the blue line. // [pause] In the coaching group, HbA1c fell by twice as much over the year — // and there was no increase in severe hypoglycaemia. That’s the main result of our study.” Speaker notes: “twice as much; no more hypos; protect: 2 vs 3”.","self_check":["The headline is a full sentence that states one point and supports your core message.","The visual shows one main comparison, highlighted and directly labelled.","Colour is not the only way to distinguish groups.","No identifiable patient information is shown, and you have the right to use every image.","Your script uses look, pause, conclude and does not read the slide."]}'::jsonb, '{"title":"Slide set review and redesign","brief":"Take the slide set of a real presentation you will give (or the slides you planned in L10 and L11). Submit: (1) the list of your slide headlines in order, rewritten as sentences, and a note on whether they tell the story of your talk and support your core message; (2) a description of two slides you have redesigned using the assertion–evidence approach, including the chart choice and what you removed; (3) an accessibility and confidentiality check of the whole set (text size, contrast, colour, abbreviations, patient information, image permissions), with what you changed; and (4) a short reflection (100–200 words) on how you will speak from the slides without reading them. Do not upload patient images or confidential material; describe slides in words.","min_words":250,"required":true,"criteria":[{"criterion":"Headlines","description":"Every slide has a sentence headline; read in order, they tell the story and support the core message."},{"criterion":"Evidence design","description":"Redesigned slides show one comparison clearly, using an appropriate chart and minimal text."},{"criterion":"Accessibility","description":"Text size, contrast and colour use are checked and corrected; colour is not used alone."},{"criterion":"Confidentiality and permissions","description":"No identifiable patient information; images are consented, anonymised or properly licensed and attributed."},{"criterion":"Delivery plan","description":"A realistic plan to speak from the slides using notes, look–pause–conclude and backup slides."}]}'::jsonb, null, null, null from public.lessons where code = 'L12'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L12');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'What is an assertion–evidence slide?', array['A slide with a topic heading and five bullet points', 'A slide with a sentence headline stating the point and visual evidence supporting it', 'A slide that contains only a quotation', 'A slide that lists all the references']::text[], 1, 'The sentence headline states the point; the body shows the evidence, with minimal text.' from public.lessons where code = 'L12';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Your results slide has nine lines of text, which you read aloud. Why is this likely to reduce comprehension?', array['Because reading aloud is impolite', 'Because congress rules forbid text', 'Because the audience reads and listens at the same time, and identical text and speech compete for attention', 'Because nine is an unlucky number']::text[], 2, 'Research on the redundancy effect found that identical on-screen text and narration presented together can reduce learning.' from public.lessons where code = 'L12';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'You need to compare the proportion of patients with complications in four hospitals. Which format is usually clearest?', array['Four pie charts', 'A three-dimensional cone chart', 'A table with all values to three decimal places', 'A bar or dot chart on a common scale, with the key hospital highlighted']::text[], 3, 'Positions on a common scale are judged more accurately than angles or areas.' from public.lessons where code = 'L12';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'Your graph shows the intervention group in red and the control group in green, with no labels. What is the main problem?', array['Viewers with red–green colour vision deficiency may not distinguish the groups', 'Red is too emotional for medical slides', 'Green is reserved for positive results', 'There is no problem if the legend is large']::text[], 0, 'Red–green colour vision deficiency is common. Use colour-blind-safe pairs and add labels, line styles or position.' from public.lessons where code = 'L12';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 5, 'You want to show a striking clinical photograph of a patient’s face. What must you do first?', array['Crop out the eyes', 'Nothing, if the audience is medical', 'Lower the image resolution', 'Obtain explicit consent and follow your institution’s policy, or use an anonymised alternative']::text[], 3, 'Identifiable images require explicit consent and institutional approval; otherwise use anonymised material.' from public.lessons where code = 'L12';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 6, 'A new data slide appears. What should you do in the first seconds?', array['Start explaining the methods immediately', 'Tell the audience where to look, pause while they look, then state the conclusion', 'Read the axis labels aloud', 'Move quickly to the next slide']::text[], 1, 'Look, pause, conclude (L07) guides the audience to the right conclusion before they interpret the graph alone.' from public.lessons where code = 'L12';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L12');
insert into public.lesson_resources (lesson_id, position, title, description, file_url, is_sample) select id, 1, 'L12 Lesson handout', 'Assertion–evidence template, chart choice guide, readability and accessibility checklist, confidentiality checklist and phrase bank.', '/materials/lessons/L12-handout.pdf', false from public.lessons where code = 'L12';

